-- Baseline schema for the VERDAD Supabase project.
--
-- Generated by scripts/dump_schema_baseline.py from the live database
-- (schemas: public, profiles). It is a snapshot of what production
-- actually runs, not a replay of the repo's history: the 29 versions in
-- supabase_migrations.schema_migrations are comment-only placeholder files next
-- to this one (most were applied out-of-band and their SQL never landed in git;
-- the rest are superseded by this file, bodies in git history), and the files
-- in supabase/database/sql/ are historical.
--
-- This file is NOT meant to be run against production. Production already has
-- every object below; mark it applied instead:
--     supabase migration repair --linked --status applied 20260915000000
-- See docs/OPERATIONS.md, 'Database schema and migrations'.
--
-- Object counts in this baseline:
--   extensions: 14
--   enums: 3
--   sequences: 0
--   tables: 27
--   constraints: 52
--   foreign keys: 33
--   views: 0
--   materialized views: 1
--   functions: 54
--   triggers: 22
--   indexes: 53
--   tables with RLS: 25
--   policies: 16
--   table grants: 84
--   function grants: 159
--   comments: 33
--   cron jobs (commented): 2

SET check_function_bodies = false;

-- Empty databases only: refuse where the schema already exists (production, or
-- any database past this version).
DO $$
BEGIN
    IF to_regclass('public.snippets') IS NOT NULL THEN
        RAISE EXCEPTION 'public.snippets already exists: do not run the baseline here; run: supabase migration repair --linked --status applied 20260915000000';
    END IF;
END
$$;

