-- --------------------------------------------------------------------------
-- Types (enums)
-- --------------------------------------------------------------------------

CREATE TYPE public.kb_entry_status AS ENUM ('active', 'superseded', 'deactivated');
CREATE TYPE public.processing_status AS ENUM ('New', 'Processing', 'Processed', 'Error', 'Ready for review', 'Reviewing');
CREATE TYPE public.validation_status AS ENUM ('false_positive', 'true_positive', 'needs_review');

-- --------------------------------------------------------------------------
-- Sequences
-- --------------------------------------------------------------------------

-- public.comment_reactions_id_seq is the identity sequence of comment_reactions.id (created with the table)
-- public.email_template_id_seq is the identity sequence of email_template.id (created with the table)
-- (no standalone sequences)

-- --------------------------------------------------------------------------
-- Tables
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS profiles.user_signups (
    id uuid NOT NULL,
    origin text,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updated_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.audio_files (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updated_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    radio_station_name text NOT NULL,
    radio_station_code text NOT NULL,
    location_state text,
    location_city text,
    recorded_at timestamp with time zone NOT NULL,
    recording_day_of_week text NOT NULL,
    file_path text NOT NULL,
    file_size bigint NOT NULL,
    status public.processing_status DEFAULT 'New'::public.processing_status NOT NULL,
    error_message text,
    starred boolean DEFAULT false
);

CREATE TABLE IF NOT EXISTS public.backfill_control (
    id text DEFAULT 'tsv_backfill'::text NOT NULL,
    enabled boolean DEFAULT false,
    batch_size integer DEFAULT 200,
    last_run_at timestamp with time zone,
    rows_processed integer DEFAULT 0,
    status text DEFAULT 'paused'::text
);

CREATE TABLE IF NOT EXISTS public.comment_reactions (
    comment_id text NOT NULL,
    emoji text NOT NULL,
    user_id text NOT NULL,
    thread_id text,
    room_id text,
    project_id text,
    added_at timestamp with time zone,
    removed_at timestamp with time zone,
    removed_by text,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text),
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL
);

CREATE TABLE IF NOT EXISTS public.comments (
    id text NOT NULL,
    thread_id text NOT NULL,
    room_id uuid NOT NULL,
    created_by text NOT NULL,
    edited_at timestamp with time zone,
    deleted_at timestamp with time zone,
    body text,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text),
    comment_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text),
    updated_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.downvote_review_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    snippet_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    downvoted_by uuid,
    downvoted_at timestamp with time zone DEFAULT now(),
    processed_at timestamp with time zone,
    kb_entries_created integer DEFAULT 0,
    error_message text,
    created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.email_template (
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    template_content text,
    template_name text
);

CREATE TABLE IF NOT EXISTS public.kb_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    fact text NOT NULL,
    related_claim text,
    confidence_score integer DEFAULT 80 NOT NULL,
    valid_from timestamp with time zone,
    valid_until timestamp with time zone,
    is_time_sensitive boolean DEFAULT false NOT NULL,
    disinformation_categories text[] DEFAULT '{}'::text[] NOT NULL,
    keywords text[] DEFAULT '{}'::text[] NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    superseded_by uuid,
    previous_version uuid,
    status public.kb_entry_status DEFAULT 'active'::public.kb_entry_status NOT NULL,
    deactivation_reason text,
    created_by_snippet uuid,
    created_by_model text
);

CREATE TABLE IF NOT EXISTS public.kb_entry_embeddings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    kb_entry uuid NOT NULL,
    embedded_document text NOT NULL,
    document_token_count integer,
    embedding extensions.vector(3072) NOT NULL,
    model_name text DEFAULT 'text-embedding-3-large'::text NOT NULL,
    status text DEFAULT 'Processed'::text NOT NULL,
    error_message text
);

CREATE TABLE IF NOT EXISTS public.kb_entry_snippet_usage (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    kb_entry uuid NOT NULL,
    snippet uuid NOT NULL,
    usage_type text NOT NULL,
    similarity_score double precision
);

CREATE TABLE IF NOT EXISTS public.kb_entry_sources (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    kb_entry uuid NOT NULL,
    url text NOT NULL,
    source_name text NOT NULL,
    source_type text NOT NULL,
    title text,
    relevant_excerpt text,
    publication_date date,
    relevance_to_claim text DEFAULT 'provides_context'::text NOT NULL,
    access_date date DEFAULT CURRENT_DATE NOT NULL
);

CREATE TABLE IF NOT EXISTS public.label_upvotes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updated_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    upvoted_by uuid NOT NULL,
    snippet_label uuid NOT NULL
);

CREATE TABLE IF NOT EXISTS public.labels (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updated_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    text text NOT NULL,
    created_by uuid,
    is_ai_suggested boolean DEFAULT false NOT NULL,
    text_spanish text
);

CREATE TABLE IF NOT EXISTS public.landing_page_content (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    key text NOT NULL,
    content_en text NOT NULL,
    content_es text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS public.prompt_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updated_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    stage text NOT NULL,
    version text NOT NULL,
    system_instruction text,
    user_prompt text,
    output_schema jsonb,
    is_active boolean DEFAULT false NOT NULL,
    description text,
    created_by text,
    sub_stage text
);

CREATE TABLE IF NOT EXISTS public.roles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    name text NOT NULL
);

CREATE TABLE IF NOT EXISTS public.snippet_embeddings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updated_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    snippet_document text NOT NULL,
    model_name text NOT NULL,
    document_token_count bigint,
    status public.processing_status NOT NULL,
    error_message text,
    embedding extensions.vector(3072),
    snippet uuid NOT NULL
);

CREATE TABLE IF NOT EXISTS public.snippet_feedback_validation_results (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updated_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    snippet uuid,
    validation_status public.validation_status NOT NULL,
    validation_confidence integer NOT NULL,
    original_claim_summary text NOT NULL,
    user_feedback_summary text NOT NULL,
    input_snippet_data jsonb NOT NULL,
    input_user_feedback jsonb NOT NULL,
    validated_by text NOT NULL,
    thought_summaries text NOT NULL,
