);

CREATE TABLE IF NOT EXISTS public.snippet_labels (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updated_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    snippet uuid NOT NULL,
    label uuid NOT NULL,
    applied_by uuid,
    upvote_count integer DEFAULT 0 NOT NULL
);

CREATE TABLE IF NOT EXISTS public.snippets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updated_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    audio_file uuid,
    start_time time without time zone,
    end_time time without time zone,
    file_path text NOT NULL,
    file_size bigint NOT NULL,
    transcription text,
    translation text,
    title jsonb,
    summary jsonb,
    explanation jsonb,
    disinformation_categories jsonb[],
    keywords_detected text[],
    language jsonb,
    confidence_scores jsonb,
    emotional_tone jsonb[],
    status public.processing_status DEFAULT 'New'::public.processing_status NOT NULL,
    error_message text,
    context jsonb,
    stage_1_llm_response uuid,
    duration time without time zone,
    recorded_at timestamp with time zone,
    political_leaning jsonb,
    comment_count integer DEFAULT 0,
    like_count integer DEFAULT 0,
    upvote_count integer DEFAULT 0,
    user_last_activity timestamp with time zone,
    previous_analysis jsonb,
    grounding_metadata text,
    reviewed_at timestamp with time zone,
    reviewed_by text,
    analyzed_by text,
    thought_summaries text,
    stage_3_prompt_version_id uuid,
    dislike_count integer DEFAULT 0
);

CREATE TABLE IF NOT EXISTS public.stage_1_llm_responses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
