ALTER TABLE public.kb_entry_snippet_usage ADD CONSTRAINT kb_entry_snippet_usage_usage_type_check CHECK ((usage_type = ANY (ARRAY['used_for_review'::text, 'triggered_creation'::text, 'triggered_update'::text])));
ALTER TABLE public.kb_entry_snippet_usage ADD CONSTRAINT kb_entry_snippet_usage_pkey PRIMARY KEY (id);
ALTER TABLE public.kb_entry_snippet_usage ADD CONSTRAINT kb_entry_snippet_usage_kb_entry_snippet_usage_type_key UNIQUE (kb_entry, snippet, usage_type);
ALTER TABLE public.kb_entry_sources ADD CONSTRAINT kb_entry_sources_relevance_to_claim_check CHECK ((relevance_to_claim = ANY (ARRAY['supports_claim'::text, 'contradicts_claim'::text, 'provides_context'::text, 'inconclusive'::text])));
ALTER TABLE public.kb_entry_sources ADD CONSTRAINT kb_entry_sources_source_type_check CHECK ((source_type = ANY (ARRAY['tier1_wire_service'::text, 'tier1_factchecker'::text, 'tier2_major_news'::text, 'tier3_regional_news'::text, 'official_source'::text, 'other'::text])));
ALTER TABLE public.kb_entry_sources ADD CONSTRAINT kb_entry_sources_pkey PRIMARY KEY (id);
ALTER TABLE public.label_upvotes ADD CONSTRAINT label_upvotes_pkey PRIMARY KEY (id);
ALTER TABLE public.label_upvotes ADD CONSTRAINT unique_upvoted_by_snippet_label UNIQUE (upvoted_by, snippet_label);
ALTER TABLE public.labels ADD CONSTRAINT labels_pkey PRIMARY KEY (id);
ALTER TABLE public.labels ADD CONSTRAINT labels_content_key UNIQUE (text);
ALTER TABLE public.landing_page_content ADD CONSTRAINT landing_page_content_pkey PRIMARY KEY (id);
ALTER TABLE public.landing_page_content ADD CONSTRAINT landing_page_content_key_key UNIQUE (key);
ALTER TABLE public.prompt_versions ADD CONSTRAINT prompt_versions_stage_check CHECK ((stage = ANY (ARRAY['stage_1'::text, 'stage_3'::text, 'stage_4'::text])));
ALTER TABLE public.prompt_versions ADD CONSTRAINT prompt_versions_pkey PRIMARY KEY (id);
ALTER TABLE public.prompt_versions ADD CONSTRAINT prompt_versions_stage_sub_stage_version_key UNIQUE (stage, sub_stage, version);
ALTER TABLE public.roles ADD CONSTRAINT roles_pkey PRIMARY KEY (id);
ALTER TABLE public.roles ADD CONSTRAINT roles_name_key UNIQUE (name);
ALTER TABLE public.snippet_embeddings ADD CONSTRAINT embedding_normalized CHECK ((abs((extensions.vector_norm(embedding) - (1.0)::double precision)) < (0.0001)::double precision));
ALTER TABLE public.snippet_embeddings ADD CONSTRAINT snippet_embeddings_pkey PRIMARY KEY (id);
ALTER TABLE public.snippet_embeddings ADD CONSTRAINT snippet_embeddings_snippet_key UNIQUE (snippet);
ALTER TABLE public.snippet_feedback_validation_results ADD CONSTRAINT snippet_feedback_validation_results_pkey PRIMARY KEY (id);
ALTER TABLE public.snippet_feedback_validation_results ADD CONSTRAINT snippet_feedback_validation_results_snippet_key UNIQUE (snippet);
