-- --------------------------------------------------------------------------
-- Views and materialized views
-- --------------------------------------------------------------------------

CREATE MATERIALIZED VIEW IF NOT EXISTS public.filter_options_cache AS
SELECT 'states'::text AS option_type,
    states.location_state AS value,
    states.location_state AS label,
    NULL::text AS secondary_value
   FROM ( SELECT DISTINCT audio_files.location_state
           FROM public.audio_files
          WHERE audio_files.location_state IS NOT NULL) states
UNION ALL
 SELECT 'sources'::text AS option_type,
    sources.radio_station_code AS value,
        CASE
            WHEN sources.radio_station_name IS NOT NULL THEN (sources.radio_station_name || ' - '::text) || sources.radio_station_code
            ELSE sources.radio_station_code
        END AS label,
    sources.radio_station_name AS secondary_value
   FROM ( SELECT DISTINCT audio_files.radio_station_code,
            audio_files.radio_station_name
           FROM public.audio_files
          WHERE audio_files.radio_station_code IS NOT NULL) sources
UNION ALL
 SELECT 'languages'::text AS option_type,
    languages.primary_language AS value,
    languages.primary_language AS label,
    NULL::text AS secondary_value
   FROM ( SELECT DISTINCT snippets.language ->> 'primary_language'::text AS primary_language
           FROM public.snippets
          WHERE snippets.language IS NOT NULL) languages;
-- filter_options_cache is populated by REFRESH MATERIALIZED VIEW, not by this file


-- --------------------------------------------------------------------------
-- Functions (trigger functions first, so the triggers below resolve)
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.draft_update_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
   NEW.updated_at = NOW();
   RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.on_downvote_queue_review()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.value = -1 THEN
        INSERT INTO user_hide_snippets (snippet)
        VALUES (NEW.snippet)
        ON CONFLICT (snippet) DO NOTHING;

        INSERT INTO downvote_review_queue (snippet_id, downvoted_by, downvoted_at)
        VALUES (NEW.snippet, NEW."user", now())
        ON CONFLICT (snippet_id) DO NOTHING;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_snippet_comment_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$BEGIN
    -- Update comment count for the snippet
    UPDATE snippets
    SET 
        comment_count = (
            SELECT COUNT(*)
            FROM comments 
            WHERE room_id = COALESCE(NEW.room_id, OLD.room_id) 
            AND deleted_at is null
        ),
        user_last_activity = NOW()
    WHERE id = COALESCE(NEW.room_id, OLD.room_id);
    
    RETURN NULL;
END;$function$;

CREATE OR REPLACE FUNCTION public.update_snippet_hidden_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    negative_count INTEGER;
BEGIN
    -- Get count of negative likes after the new insertion
    SELECT COUNT(*) INTO negative_count
    FROM user_like_snippets uls 
    WHERE snippet = NEW.snippet AND uls.value = -1;

    -- Only proceed if this is a negative like (value = -1) and the total count is exactly 2
    IF NEW.value = -1 AND negative_count = 2 THEN
        -- Insert into user_hide_snippets if not already exists
        INSERT INTO user_hide_snippets (snippet)
        SELECT NEW.snippet
        WHERE NOT EXISTS (
            SELECT 1 
            FROM user_hide_snippets 
            WHERE snippet = NEW.snippet
        );
    END IF;
    
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_snippet_like_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE snippets
    SET
        like_count = (
            SELECT COUNT(*)
            FROM user_like_snippets
            WHERE snippet = COALESCE(NEW.snippet, OLD.snippet)
            AND value = 1
        ),
        dislike_count = (
            SELECT COUNT(*)
            FROM user_like_snippets
            WHERE snippet = COALESCE(NEW.snippet, OLD.snippet)
            AND value = -1
        ),
        user_last_activity = NOW()
    WHERE id = COALESCE(NEW.snippet, OLD.snippet);

    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_snippet_upvote_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$DECLARE
    snippet_id UUID;
    snippet_label_id UUID;
BEGIN
    snippet_label_id := COALESCE(NEW.snippet_label, OLD.snippet_label);

    UPDATE snippet_labels
    SET upvote_count = (
        SELECT COUNT(*)
        FROM label_upvotes
        WHERE snippet_label = snippet_label_id
    )
    WHERE id = snippet_label_id
    RETURNING snippet INTO snippet_id;

    IF snippet_id IS NOT NULL THEN
        UPDATE snippets
        SET 
            upvote_count = (
                SELECT COUNT(*)
                FROM label_upvotes lu
                JOIN snippet_labels sl ON lu.snippet_label = sl.id
                WHERE sl.snippet = snippet_id
            ),
            user_last_activity = NOW()
        WHERE id = snippet_id;
    END IF;
    
    RETURN NULL;
END;$function$;

CREATE OR REPLACE FUNCTION public.update_tsv_transcription()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.tsv_transcription := to_tsvector('spanish', COALESCE(NEW.initial_transcription, ''));
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION profiles.handle_new_signup(jwt jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
begin
  -- First insert the signup data
  insert into profiles.user_signups (
    id,
    email,
    auth_method,
    signup_url,
    signup_timestamp
  )
  values (
    (jwt->>'sub')::uuid,
    jwt->>'email',
    jwt->>'aal',
    nullif(current_setting('request.headers', true), '')::json->>'origin',
    now()
  );

  -- Return the unmodified JWT
  return jwt;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_apply_and_upvote_label(snippet_id uuid, label_text text, p_language text DEFAULT 'english'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    snippet_label_id UUID;
    label_id UUID;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Ensure that the label exists
    SELECT id INTO label_id
    FROM public.labels
    WHERE text = label_text OR text_spanish = label_text
    LIMIT 1;

    IF label_id IS NULL THEN
        -- Create the label
        INSERT INTO public.labels (created_by, is_ai_suggested, text, text_spanish)
        VALUES (current_user_id, FALSE, label_text, label_text)
        RETURNING id INTO label_id;
    END IF;

    -- Ensure that the label is applied to the snippet
    SELECT id INTO snippet_label_id
    FROM public.snippet_labels
    WHERE snippet = snippet_id AND label = label_id;

    IF snippet_label_id IS NULL THEN
        -- Apply the label to the snippet
        INSERT INTO public.snippet_labels (snippet, label, applied_by)
        VALUES (snippet_id, label_id, current_user_id)
        RETURNING id INTO snippet_label_id;
    END IF;

    -- Proceed to upvote the label
    INSERT INTO public.label_upvotes (upvoted_by, snippet_label)
    VALUES (current_user_id, snippet_label_id)
    ON CONFLICT (upvoted_by, snippet_label) DO NOTHING;

    -- Return the result of the get_snippet_labels function
    RETURN get_snippet_labels(snippet_id, p_language);
END;
$function$;

CREATE OR REPLACE FUNCTION public.dismiss_welcome_card()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$DECLARE
    current_user_id UUID;
    metadata jsonb;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Get existing metadata and create new object
    SELECT COALESCE(raw_user_meta_data, '{}'::jsonb) || 
           jsonb_build_object('dismiss_welcome_card', true)
    INTO metadata
    FROM auth.users
    WHERE id = current_user_id;

    -- Update the user's profile in the auth.users table
    UPDATE auth.users
    SET
        raw_user_meta_data = metadata,
        updated_at = now() AT TIME ZONE 'utc'
    WHERE id = current_user_id;

    RETURN jsonb_build_object('status', 'success', 'message', 'Welcome card has been dismissed successfully');
END;$function$;

CREATE OR REPLACE FUNCTION public.fetch_a_new_audio_file_and_reserve_it()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    audio_file_record jsonb;
BEGIN
    UPDATE public.audio_files
    SET status = 'Processing'
    WHERE id = (
        SELECT id
        FROM public.audio_files
        WHERE status = 'New'
        ORDER BY recorded_at DESC
        LIMIT 1
        FOR UPDATE SKIP LOCKED
    )
    RETURNING row_to_json(public.audio_files.*) INTO audio_file_record;

    RETURN audio_file_record;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fetch_a_new_snippet_and_reserve_it()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$ 
DECLARE     
    snippet_record jsonb; 
BEGIN     
    UPDATE public.snippets     
    SET status = 'Processing'     
    WHERE id = (         
        SELECT id         
        FROM public.snippets         
        WHERE status = 'New'         
        ORDER BY recorded_at DESC
        LIMIT 1         
        FOR UPDATE SKIP LOCKED     
    )     
    RETURNING (         
        row_to_json(public.snippets.*)::jsonb - 'audio_file'::text - 'stage_1_llm_response'::text     
    ) || jsonb_build_object(         
        'audio_file', (             
            SELECT jsonb_build_object(                 
                'radio_station_name', af.radio_station_name,                 
                'radio_station_code', af.radio_station_code,                 
                'location_state', af.location_state,                 
                'location_city', af.location_city,                 
                'recorded_at', af.recorded_at,                 
                'recording_day_of_week', af.recording_day_of_week             
            )             
            FROM public.audio_files af             
            WHERE af.id = public.snippets.audio_file         
        ),         
        'stage_1_llm_response', (             
            SELECT jsonb_build_object(                 
                'detection_result', s1lr.detection_result             
            )             
            FROM public.stage_1_llm_responses s1lr             
            WHERE s1lr.id = public.snippets.stage_1_llm_response         
        )     
    ) INTO snippet_record;      

    RETURN snippet_record; 
END;  
$function$;

CREATE OR REPLACE FUNCTION public.fetch_a_new_stage_1_llm_response_and_reserve_it()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    stage_1_llm_response_record jsonb;
BEGIN
    UPDATE public.stage_1_llm_responses
    SET status = 'Processing'
    WHERE id = (
        SELECT id
        FROM public.stage_1_llm_responses
        WHERE status = 'New'
        ORDER BY created_at DESC
        LIMIT 1
        FOR UPDATE SKIP LOCKED
    )
    RETURNING (
        row_to_json(public.stage_1_llm_responses.*)::jsonb - 'audio_file'::text 
    ) || jsonb_build_object(
        'audio_file', (
            SELECT jsonb_build_object(
                'id', af.id,
                'file_path', af.file_path,
                'recorded_at', af.recorded_at
            )
            FROM public.audio_files af
            WHERE af.id = public.stage_1_llm_responses.audio_file
        )
    ) INTO stage_1_llm_response_record;

    RETURN stage_1_llm_response_record;
END; 
$function$;

CREATE OR REPLACE FUNCTION public.fetch_a_ready_for_review_snippet_and_reserve_it()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    snippet_record jsonb;
BEGIN
    UPDATE public.snippets
    SET status = 'Reviewing'
    WHERE id = (
        SELECT id
        FROM public.snippets
        WHERE status = 'Ready for review'
        ORDER BY recorded_at DESC
        LIMIT 1
        FOR UPDATE SKIP LOCKED
    )
    RETURNING (row_to_json(public.snippets.*)::jsonb) INTO snippet_record;

    RETURN snippet_record;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fetch_a_snippet_that_has_no_embedding()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    -- Return a single snippet that:
    -- 1. Has status 'Processed'
    -- 2. Has no corresponding embedding (using NOT IN with hash)
    -- 3. Is the most recently recorded
    RETURN (
        SELECT row_to_json(s.*)::jsonb
        FROM public.snippets s
        WHERE s.status = 'Processed'
        AND s.id NOT IN (SELECT snippet FROM snippet_embeddings)
        ORDER BY s.recorded_at DESC
        LIMIT 1
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.find_duplicate_kb_entries(query_embedding extensions.vector, similarity_threshold double precision DEFAULT 0.92, max_results integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    query_sub_embedding vector(512);
    result jsonb;
BEGIN
    query_sub_embedding := sub_vector(query_embedding, 512)::vector(512);

    WITH candidates AS (
        SELECT
            ke.id AS entry_id,
            kee.embedding
        FROM kb_entry_embeddings kee
        JOIN kb_entries ke ON ke.id = kee.kb_entry
        WHERE kee.status = 'Processed'
            -- Search across ALL statuses for deduplication
        ORDER BY
            sub_vector(kee.embedding, 512)::vector(512) <#> query_sub_embedding ASC
        LIMIT max_results * 4
    ),
    ranked AS (
        SELECT
            c.entry_id,
            -(c.embedding <#> query_embedding) AS similarity
        FROM candidates c
        WHERE -(c.embedding <#> query_embedding) > similarity_threshold
        ORDER BY c.embedding <#> query_embedding ASC
        LIMIT max_results
    ),
    final_entries AS (
        SELECT
            jsonb_build_object(
                'id', ke.id,
                'fact', ke.fact,
                'related_claim', ke.related_claim,
                'confidence_score', ke.confidence_score,
                'status', ke.status::TEXT,
                'version', ke.version,
                'similarity', r.similarity
            ) AS entry
        FROM ranked r
        JOIN kb_entries ke ON ke.id = r.entry_id
        ORDER BY r.similarity DESC
    )
    SELECT jsonb_agg(fe.entry)
    INTO result
    FROM final_entries fe;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_filtering_options(p_language text DEFAULT 'english'::text, p_label_page integer DEFAULT 0, p_label_page_size integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    result jsonb;
    labels jsonb;
    states jsonb;
    sources jsonb;
    languages jsonb;
    total_labels INT;
    total_pages INT;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Fetch total number of labels
    SELECT COUNT(*) INTO total_labels
    FROM public.labels;

    -- Calculate total pages
    total_pages := CEIL(total_labels::FLOAT / p_label_page_size);

    -- Fetch paginated labels based on the language
    SELECT jsonb_agg(
        jsonb_build_object(
            'value', id,
            'label', CASE
                WHEN p_language = 'spanish' THEN text_spanish
                ELSE text
            END
        )
    ) INTO labels
    FROM (
        SELECT id, text, text_spanish
        FROM public.labels
        ORDER BY created_at
        LIMIT p_label_page_size OFFSET p_label_page * p_label_page_size
    ) AS paginated_labels;

    -- Add pagination info to labels
    labels := jsonb_build_object(
        'current_page', p_label_page,
        'page_size', p_label_page_size,
        'total_pages', total_pages,
        'items', labels
    );

    -- Fetch states from cached view (fast!)
    SELECT jsonb_agg(
        jsonb_build_object(
            'label', label,
            'value', value
        )
    ) INTO states
    FROM filter_options_cache
    WHERE option_type = 'states';

    -- Fetch sources from cached view (fast!)
    SELECT jsonb_agg(
        jsonb_build_object(
            'label', label,
            'value', value
        )
    ) INTO sources
    FROM filter_options_cache
    WHERE option_type = 'sources';

    -- Fetch languages from cached view (fast!)
    SELECT jsonb_agg(
        jsonb_build_object(
            'label', label,
            'value', value
        )
    ) INTO languages
    FROM filter_options_cache
    WHERE option_type = 'languages';

    RETURN jsonb_build_object(
        'languages', languages,
        'states', states,
        'sources', sources,
        'labeledBy', jsonb_build_array(
            jsonb_build_object('label', 'by Me', 'value', 'by_me'),
            jsonb_build_object('label', 'by Others', 'value', 'by_others')
        ),
        'starredBy', jsonb_build_array(
            jsonb_build_object('label', 'by Me', 'value', 'by_me'),
            jsonb_build_object('label', 'by Others', 'value', 'by_others')
        ),
        'labels', labels
    );
END; $function$;

CREATE OR REPLACE FUNCTION public.get_landing_page_content()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$ 
DECLARE     
    result jsonb;     
    snippets jsonb; 
BEGIN     
    SELECT jsonb_object_agg(key, jsonb_build_object('english', content_en, 'spanish', content_es))     
    INTO result     
    FROM public.landing_page_content     
    WHERE key IN ('hero_title', 'hero_description', 'footer_text'); 

    SELECT jsonb_agg(snippet) INTO snippets     
    FROM (         
        SELECT jsonb_build_object(             
            'id', s.id,             
            'title', s.title,             
            'labels', COALESCE((                 
                SELECT jsonb_agg(jsonb_build_object(                     
                    'english', l.text,                     
                    'spanish', l.text_spanish                 
                ))                 
                FROM public.snippet_labels sl                 
                JOIN public.labels l ON sl.label = l.id                 
                WHERE sl.snippet = s.id             
            ), '[]'::jsonb)         
        ) AS snippet         
        FROM public.snippets s         
        JOIN public.user_star_snippets us ON us.snippet = s.id         
        ORDER BY (s.confidence_scores->>'overall')::numeric DESC -- Order by highest confidence score         
        LIMIT 10     
    ) AS limited_snippets; 

    RETURN jsonb_build_object(         
        'content', COALESCE(result, '{}'::jsonb),         
        'snippets', COALESCE(snippets, '[]'::jsonb)     
    ); 
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_snippet(snippet_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    is_hidden BOOLEAN;
    result jsonb;
BEGIN
    -- Check if the snippet is currently hidden
    SELECT EXISTS (SELECT 1 FROM user_hide_snippets uhs WHERE uhs.snippet = snippet_id) INTO is_hidden;

    -- If the snippet is hidden, return an empty JSON object
    IF is_hidden THEN
        RETURN '{}'::jsonb;
    END IF;

    SELECT jsonb_build_object(
        'id', s.id,
        'recorded_at', s.recorded_at,
        'audio_file', jsonb_build_object(
            'radio_station_name', a.radio_station_name,
            'radio_station_code', a.radio_station_code,
            'location_state', a.location_state,
            'location_city', a.location_city
        ),
        'duration', s.duration,
        'start_time', s.start_time,
        'end_time', s.end_time,
        'file_path', s.file_path,
        'file_size', s.file_size,
        'title', s.title ->> 'english',
        'summary', s.summary ->> 'english',
        'language', CASE
            WHEN s.language IS NULL THEN NULL
            ELSE s.language ->> 'primary_language'
        END,
        'context', s.context
    ) INTO result
    FROM snippets s
    LEFT JOIN audio_files a ON s.audio_file = a.id
    WHERE s.id = snippet_id AND s.status = 'Processed';

    RETURN COALESCE(result, '{}'::jsonb);
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_recording_details(p_recording_id uuid, p_language text DEFAULT 'english'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    result JSONB;
    recording_exists BOOLEAN;
BEGIN
    SELECT EXISTS(SELECT 1 FROM audio_files WHERE id = p_recording_id) INTO recording_exists;
    IF NOT recording_exists THEN
        RETURN jsonb_build_object('error', 'Recording not found');
    END IF;

    SELECT jsonb_build_object(
        'id', af.id,
        'radio_station_name', af.radio_station_name,
        'radio_station_code', af.radio_station_code,
        'location_state', af.location_state,
        'location_city', af.location_city,
        'recorded_at', af.recorded_at,
        'recording_day_of_week', af.recording_day_of_week,
        'file_path', af.file_path,
        'file_size', af.file_size,
        'status', af.status,
        'starred', COALESCE(af.starred, FALSE),
        'created_at', af.created_at,
        'transcript', jsonb_build_object(
            'initial_transcription', s1.initial_transcription,
            'timestamped_transcription', s1.timestamped_transcription,
            'transcriptor', s1.transcriptor
        ),
        'snippet_count', (SELECT COUNT(*) FROM snippets s WHERE s.audio_file = af.id AND s.status = 'Processed'),
        'has_snippets', (SELECT COUNT(*) > 0 FROM snippets s WHERE s.audio_file = af.id AND s.status = 'Processed'),
        'snippets', COALESCE(
            (SELECT jsonb_agg(
                jsonb_build_object(
                    'id', s.id,
                    'title', CASE WHEN p_language = 'spanish' THEN COALESCE(s.title->>'spanish', s.title->>'english') ELSE COALESCE(s.title->>'english', s.title->>'spanish') END,
                    'summary', CASE WHEN p_language = 'spanish' THEN COALESCE(s.summary->>'spanish', s.summary->>'english') ELSE COALESCE(s.summary->>'english', s.summary->>'spanish') END,
                    'start_time', s.start_time,
                    'end_time', s.end_time,
                    'duration', s.duration,
                    'file_path', s.file_path,
                    'transcription', s.transcription,
                    'translation', s.translation,
                    'confidence_scores', s.confidence_scores,
                    'language', s.language,
                    'labels', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', l.id, 'text', CASE WHEN p_language = 'spanish' THEN COALESCE(l.text_spanish, l.text) ELSE l.text END)), '[]'::jsonb) FROM snippet_labels sl JOIN labels l ON sl.label = l.id WHERE sl.snippet = s.id)
                ) ORDER BY s.start_time
            ) FROM snippets s WHERE s.audio_file = af.id AND s.status = 'Processed'),
            '[]'::jsonb
        )
    ) INTO result
    FROM audio_files af
    LEFT JOIN stage_1_llm_responses s1 ON s1.audio_file = af.id
    WHERE af.id = p_recording_id;

    RETURN result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_recordings_preview(p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 20, p_filter jsonb DEFAULT '{}'::jsonb, p_search_term text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    result JSONB;
    next_cursor TIMESTAMP WITH TIME ZONE;
    has_more BOOLEAN;
    trimmed_search_term TEXT := TRIM(COALESCE(p_search_term, ''));
    search_query tsquery;
    filter_state TEXT;
    filter_radio_station TEXT;
    filter_has_snippets TEXT;
    filter_starred BOOLEAN;
    filter_label TEXT;
    filter_language TEXT;
    filter_transcribed_only BOOLEAN;
BEGIN
    filter_state := p_filter->>'state';
    filter_radio_station := p_filter->>'radio_station';
    filter_has_snippets := p_filter->>'has_snippets';
    filter_starred := (p_filter->>'starred')::BOOLEAN;
    filter_label := p_filter->>'label';
    filter_language := p_filter->>'language';
    filter_transcribed_only := COALESCE((p_filter->>'transcribed_only')::BOOLEAN, FALSE);

    IF trimmed_search_term <> '' THEN
        search_query := websearch_to_tsquery('spanish', trimmed_search_term);
    END IF;

    -- Create temp table WITHOUT search_excerpt for fast filtering
    CREATE TEMP TABLE temp_recordings ON COMMIT DROP AS
    SELECT
        af.id,
        af.radio_station_name,
        af.radio_station_code,
        af.location_state,
        af.location_city,
        af.recorded_at,
        af.recording_day_of_week,
        af.file_path,
        af.file_size,
        af.status,
        COALESCE(af.starred, FALSE) AS starred,
        s1.id AS stage_1_id,
        s1.initial_transcription,  -- Keep for ts_headline later
        0 AS snippet_count,
        EXISTS (
            SELECT 1 FROM snippets s
            WHERE s.audio_file = af.id AND s.status = 'Processed'
        ) AS has_snippets,
        COALESCE(
            (SELECT s.language->>'primary_language'
             FROM snippets s
             WHERE s.audio_file = af.id
             LIMIT 1),
            'Unknown'
        ) AS primary_language
    FROM audio_files af
    LEFT JOIN stage_1_llm_responses s1 ON s1.audio_file = af.id
    WHERE
        (p_cursor IS NULL OR af.recorded_at < p_cursor)
        AND (filter_state IS NULL OR af.location_state = filter_state)
        AND (filter_radio_station IS NULL OR af.radio_station_name = filter_radio_station)
        AND (
            filter_has_snippets IS NULL
            OR filter_has_snippets = 'all'
            OR (filter_has_snippets = 'with' AND EXISTS (
                SELECT 1 FROM snippets s WHERE s.audio_file = af.id AND s.status = 'Processed'
            ))
            OR (filter_has_snippets = 'without' AND NOT EXISTS (
                SELECT 1 FROM snippets s WHERE s.audio_file = af.id AND s.status = 'Processed'
            ))
        )
        AND (filter_starred IS NULL OR filter_starred = FALSE OR af.starred = TRUE)
        AND (
            filter_label IS NULL
            OR EXISTS (
                SELECT 1
                FROM snippets s
                JOIN snippet_labels sl ON sl.snippet = s.id
                JOIN labels l ON sl.label = l.id
                WHERE s.audio_file = af.id
                  AND (l.text ILIKE '%' || filter_label || '%' OR l.text_spanish ILIKE '%' || filter_label || '%')
            )
        )
        AND (
            filter_language IS NULL
            OR EXISTS (
                SELECT 1
                FROM snippets s
                WHERE s.audio_file = af.id
                  AND s.language->>'primary_language' ILIKE '%' || filter_language || '%'
            )
        )
        AND (filter_transcribed_only = FALSE OR s1.id IS NOT NULL)
        AND (search_query IS NULL OR s1.tsv_transcription @@ search_query)
    ORDER BY af.recorded_at DESC
    LIMIT p_limit + 1;

    UPDATE temp_recordings tr
    SET snippet_count = (
        SELECT COUNT(*)
        FROM snippets s
        WHERE s.audio_file = tr.id AND s.status = 'Processed'
    );

    SELECT COUNT(*) > p_limit INTO has_more FROM temp_recordings;

    SELECT recorded_at INTO next_cursor
    FROM temp_recordings
    ORDER BY recorded_at DESC
    OFFSET p_limit - 1
    LIMIT 1;

    -- Build JSON with ts_headline computed ONLY for returned rows
    SELECT jsonb_build_object(
        'recordings', COALESCE(
            (SELECT jsonb_agg(
                jsonb_build_object(
                    'id', tr.id,
                    'radio_station_name', tr.radio_station_name,
                    'radio_station_code', tr.radio_station_code,
                    'location_state', tr.location_state,
                    'location_city', tr.location_city,
                    'recorded_at', tr.recorded_at,
                    'recording_day_of_week', tr.recording_day_of_week,
                    'file_path', tr.file_path,
                    'file_size', tr.file_size,
                    'status', tr.status,
                    'starred', tr.starred,
                    'snippet_count', tr.snippet_count,
                    'has_snippets', tr.has_snippets,
                    'primary_language', tr.primary_language,
                    'search_excerpt', CASE
                        WHEN search_query IS NOT NULL AND tr.initial_transcription IS NOT NULL THEN
                            ts_headline('spanish', tr.initial_transcription, search_query,
                                'MaxWords=35, MinWords=15, ShortWord=3, MaxFragments=1')
                        ELSE NULL
                    END
                )
            )
            FROM (
                SELECT * FROM temp_recordings
                ORDER BY recorded_at DESC
                LIMIT p_limit
            ) tr),
            '[]'::jsonb
        ),
        'next_cursor', next_cursor,
        'has_more', has_more,
        'total_count', NULL
    ) INTO result;

    RETURN result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_roles()
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    user_roles text[];
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Get the role names from the roles table by joining with user_roles
    SELECT array_agg(r.name) INTO user_roles
    FROM public.user_roles ur
    JOIN public.roles r ON ur.role = r.id
    WHERE ur."user" = current_user_id;

    RETURN COALESCE(user_roles, '{}');
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_snippet(snippet_id uuid, p_language text DEFAULT 'english'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    user_roles TEXT[];
    is_hidden BOOLEAN;
    result jsonb;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Get the role names from the roles table by joining with user_roles
    SELECT array_agg(r.name) INTO user_roles
    FROM public.user_roles ur
    JOIN public.roles r ON ur.role = r.id
    WHERE ur."user" = current_user_id;

    -- Check if the snippet is currently hidden
    SELECT EXISTS (SELECT 1 FROM user_hide_snippets uhs WHERE uhs.snippet = snippet_id) INTO is_hidden;

    -- If the user does not have "admin" role and the snippet is currently hidden, do not return it
    IF (
        user_roles IS NULL
        OR ARRAY_LENGTH(user_roles, 1) = 0
        OR 'admin' <> ANY(user_roles)
    )
    AND is_hidden THEN RETURN '{}'::jsonb;

    END IF;

    -- Return the specified snippet, if its status is processed
    SELECT jsonb_build_object(
        'id', s.id,
        'recorded_at', s.recorded_at,
        'audio_file', jsonb_build_object(
            'id', a.id,
            'radio_station_name', a.radio_station_name,
            'radio_station_code', a.radio_station_code,
            'location_state', a.location_state,
            'location_city', a.location_city
        ),
        'duration', s.duration,
        'start_time', s.start_time,
        'end_time', s.end_time,
        'file_path', s.file_path,
        'file_size', s.file_size,
        'title', CASE
            WHEN p_language = 'spanish' THEN s.title ->> 'spanish'
            ELSE s.title ->> 'english'
        END,
        'summary', CASE
            WHEN p_language = 'spanish' THEN s.summary ->> 'spanish'
            ELSE s.summary ->> 'english'
        END,
        'explanation', CASE
            WHEN p_language = 'spanish' THEN s.explanation ->> 'spanish'
            ELSE s.explanation ->> 'english'
        END,
        'confidence_scores', s.confidence_scores,
        'language', s.language,
        'context', s.context,
        'starred_by_user', CASE
            WHEN us.id IS NOT NULL THEN true
            ELSE false
        END,
        'user_like_status', ul.value,
        'like_count', (SELECT COUNT(*) FROM user_like_snippets uls WHERE uls.snippet = s.id AND uls.value = 1),
        'dislike_count', (SELECT COUNT(*) FROM user_like_snippets uls WHERE uls.snippet = s.id AND uls.value = -1),
        'political_leaning', s.political_leaning,
        'status', s.status,
        'error_message', s.error_message,
        'labels', get_snippet_labels(s.id, p_language) -> 'labels',
        'hidden', is_hidden
    ) INTO result
    FROM snippets s
    LEFT JOIN user_star_snippets us ON s.id = us.snippet AND us."user" = current_user_id
    LEFT JOIN user_like_snippets ul ON s.id = ul.snippet AND ul."user" = current_user_id
    LEFT JOIN audio_files a ON s.audio_file = a.id
    WHERE s.id = snippet_id AND s.status = 'Processed';

    RETURN COALESCE(result, '{}'::jsonb);
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_snippet_details(snippet_id uuid, p_language text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    result jsonb;
BEGIN
    -- Get current user and validate
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Get detailed snippet data
    SELECT jsonb_build_object(
        'id', s.id,
        'recorded_at', s.recorded_at,
        'duration', s.duration,
        'start_time', s.start_time,
        'end_time', s.end_time,
        'file_path', s.file_path,
        'file_size', s.file_size,
        'political_leaning', s.political_leaning,
        'title', CASE
            WHEN p_language = 'spanish' THEN s.title ->> 'spanish'
            ELSE s.title ->> 'english'
        END,
        'summary', CASE
            WHEN p_language = 'spanish' THEN s.summary ->> 'spanish'
            ELSE s.summary ->> 'english'
        END,
        'explanation', CASE
            WHEN p_language = 'spanish' THEN s.explanation ->> 'spanish'
            ELSE s.explanation ->> 'english'
        END,
        'transcription', s.transcription,
        'translation', s.translation,
        'confidence_scores', s.confidence_scores,
        'language', s.language,
        'context', s.context,
        'labels', (get_snippet_labels(s.id, p_language) -> 'labels'),
        'audio_file', jsonb_build_object(
            'id', a.id,
            'radio_station_name', a.radio_station_name,
            'radio_station_code', a.radio_station_code,
            'location_state', a.location_state,
            'location_city', a.location_city
        ),
        'starred_by_user', CASE
            WHEN us.id IS NOT NULL THEN true
            ELSE false
        END,
        'user_like_status', ul.value,
        'like_count', COUNT(*) FILTER (WHERE uls.value = 1),
        'dislike_count', COUNT(*) FILTER (WHERE uls.value = -1),
        'hidden', uhs.snippet IS NOT NULL,
        'comment_count', (
            SELECT COUNT(*)
            FROM snippet_comments sc
            WHERE sc.snippet = s.id
        ),
        'upvote_count', (
            SELECT COUNT(*)
            FROM label_upvotes lu
            JOIN snippet_labels sl ON lu.snippet_label = sl.id
            WHERE sl.snippet = s.id
        )
    ) INTO result
    FROM snippets s
    LEFT JOIN audio_files a ON s.audio_file = a.id
    LEFT JOIN user_star_snippets us ON us.snippet = s.id AND us."user" = current_user_id
    LEFT JOIN user_like_snippets ul ON ul.snippet = s.id AND ul."user" = current_user_id
    LEFT JOIN user_like_snippets uls ON uls.snippet = s.id
    LEFT JOIN user_hide_snippets uhs ON uhs.snippet = s.id
    WHERE s.id = snippet_id
    GROUP BY s.id, a.id, us.id, ul.value, uhs.snippet;

    RETURN result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_snippet_labels(snippet_id uuid, p_language text DEFAULT 'english'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    result jsonb;
    current_user_id UUID;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    SELECT jsonb_build_object(
        'snippet_id', snippet_id,
        'labels', COALESCE(jsonb_agg(jsonb_build_object(
            'id', l.id,
            'text', CASE
                WHEN p_language = 'spanish' THEN l.text_spanish
                ELSE l.text
            END,
            'upvote_count', COALESCE(upvote_counts.count, 0),
            'upvoted_by_me', COALESCE(upvote_counts.upvoted_by_current_user, false)
        )), '[]'::jsonb)
    ) INTO result
    FROM public.snippet_labels sl
    JOIN public.labels l ON sl.label = l.id
    LEFT JOIN LATERAL (
        SELECT
            COUNT(*) AS count,
            BOOL_OR(lu.upvoted_by = current_user_id) AS upvoted_by_current_user
        FROM public.label_upvotes lu
        WHERE lu.snippet_label = sl.id
    ) upvote_counts ON TRUE
    WHERE sl.snippet = snippet_id;

    RETURN COALESCE(result, jsonb_build_object('snippet_id', snippet_id, 'labels', '[]'::jsonb));
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_snippets(p_language text, p_filter jsonb, page integer, page_size integer, p_order_by text, p_search_term text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    result jsonb;
    total_count INTEGER;
    total_pages INTEGER;
    user_roles TEXT[];
    user_is_admin BOOLEAN;
    trimmed_search_term TEXT := TRIM(p_search_term);
    -- Filter detection flags for optimization
    has_starred_filter BOOLEAN;
    starred_by_me BOOLEAN;
    starred_by_others BOOLEAN;
    has_labeled_filter BOOLEAN;
    labeled_by_me BOOLEAN;
    labeled_by_others BOOLEAN;
    has_upvoted_filter BOOLEAN;
    filter_upvoted_by_me BOOLEAN;
    filter_upvoted_by_others BOOLEAN;
    -- State/source filter flags
    has_state_filter BOOLEAN;
    has_source_filter BOOLEAN;
BEGIN
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    SELECT array_agg(r.name) INTO user_roles
    FROM public.user_roles ur
    JOIN public.roles r ON ur.role = r.id
    WHERE ur."user" = current_user_id;

    user_is_admin := COALESCE('admin' = ANY(user_roles), FALSE);

    -- Pre-compute filter flags to enable query optimization
    has_starred_filter := p_filter IS NOT NULL
        AND p_filter ? 'starredBy'
        AND jsonb_array_length(p_filter->'starredBy') > 0;
    starred_by_me := has_starred_filter AND p_filter->'starredBy' ? 'by_me';
    starred_by_others := has_starred_filter AND p_filter->'starredBy' ? 'by_others';

    has_labeled_filter := p_filter IS NOT NULL
        AND p_filter ? 'labeledBy'
        AND jsonb_array_length(p_filter->'labeledBy') > 0;
    labeled_by_me := has_labeled_filter AND p_filter->'labeledBy' ? 'by_me';
    labeled_by_others := has_labeled_filter AND p_filter->'labeledBy' ? 'by_others';

    has_upvoted_filter := p_filter IS NOT NULL
        AND p_filter ? 'upvotedBy'
        AND jsonb_array_length(p_filter->'upvotedBy') > 0;
    filter_upvoted_by_me := has_upvoted_filter AND p_filter->'upvotedBy' ? 'by_me';
    filter_upvoted_by_others := has_upvoted_filter AND p_filter->'upvotedBy' ? 'by_others';

    -- State/source filter flags
    has_state_filter := p_filter IS NOT NULL
        AND p_filter ? 'states'
        AND jsonb_array_length(p_filter->'states') > 0;
    has_source_filter := p_filter IS NOT NULL
        AND p_filter ? 'sources'
        AND jsonb_array_length(p_filter->'sources') > 0;

    WITH
    -- Pre-filter CTEs (defined once, reused by filtered_snippets)
    starred_snippet_ids AS (
        SELECT DISTINCT uss.snippet
        FROM user_star_snippets uss
        WHERE has_starred_filter AND (
            (starred_by_me AND starred_by_others) OR
            (starred_by_me AND NOT starred_by_others AND uss."user" = current_user_id) OR
            (starred_by_others AND NOT starred_by_me AND uss."user" != current_user_id)
        )
    ),
    labeled_snippet_ids AS (
        SELECT DISTINCT sl.snippet
        FROM snippet_labels sl
        JOIN label_upvotes lu ON lu.snippet_label = sl.id
        WHERE has_labeled_filter AND (
            (labeled_by_me AND labeled_by_others) OR
            (labeled_by_me AND NOT labeled_by_others AND lu.upvoted_by = current_user_id) OR
            (labeled_by_others AND NOT labeled_by_me AND lu.upvoted_by != current_user_id)
        )
    ),
    upvoted_snippet_ids AS (
        SELECT DISTINCT sl.snippet
        FROM snippet_labels sl
        JOIN label_upvotes lu ON lu.snippet_label = sl.id
        WHERE has_upvoted_filter AND (
            (filter_upvoted_by_me AND filter_upvoted_by_others) OR
            (filter_upvoted_by_me AND NOT filter_upvoted_by_others AND lu.upvoted_by = current_user_id) OR
            (filter_upvoted_by_others AND NOT filter_upvoted_by_me AND lu.upvoted_by != current_user_id)
        )
    ),
    state_filtered_audio_ids AS (
        SELECT id FROM audio_files
        WHERE has_state_filter
        AND location_state IN (SELECT jsonb_array_elements_text(p_filter->'states'))
    ),
    source_filtered_audio_ids AS (
        SELECT id FROM audio_files
        WHERE has_source_filter
        AND radio_station_code IN (SELECT jsonb_array_elements_text(p_filter->'sources'))
    ),
    search_matched_ids AS (
        SELECT s.id
        FROM snippets s
        WHERE trimmed_search_term != '' AND (
            (s.title ->> 'english') &@ trimmed_search_term
            OR (s.title ->> 'spanish') &@ trimmed_search_term
            OR (s.explanation ->> 'english') &@ trimmed_search_term
            OR (s.explanation ->> 'spanish') &@ trimmed_search_term
            OR (s.summary ->> 'english') &@ trimmed_search_term
            OR (s.summary ->> 'spanish') &@ trimmed_search_term
            OR s.transcription &@ trimmed_search_term
            OR s.translation &@ trimmed_search_term
        )
    ),
    -- Lightweight filtered IDs (for count + pagination, no heavy columns)
    filtered_snippets AS (
        SELECT
            s.id,
            s.recorded_at,
            s.user_last_activity,
            s.upvote_count,
            s.comment_count,
            COALESCE(s.like_count, 0) AS like_count
        FROM snippets s
        LEFT JOIN user_hide_snippets uhs ON uhs.snippet = s.id
        LEFT JOIN starred_snippet_ids ssi ON ssi.snippet = s.id
        LEFT JOIN labeled_snippet_ids lsi ON lsi.snippet = s.id
        LEFT JOIN upvoted_snippet_ids usi ON usi.snippet = s.id
        LEFT JOIN state_filtered_audio_ids sfa ON sfa.id = s.audio_file
        LEFT JOIN source_filtered_audio_ids srfa ON srfa.id = s.audio_file
        LEFT JOIN search_matched_ids smi ON smi.id = s.id
        WHERE s.status = 'Processed' AND (s.confidence_scores->>'overall')::INTEGER >= 95
        AND (user_is_admin OR uhs.snippet IS NULL)
        AND (NOT has_starred_filter OR ssi.snippet IS NOT NULL)
        AND (NOT has_labeled_filter OR lsi.snippet IS NOT NULL)
        AND (NOT has_upvoted_filter OR usi.snippet IS NOT NULL)
        AND (NOT has_state_filter OR sfa.id IS NOT NULL)
        AND (NOT has_source_filter OR srfa.id IS NOT NULL)
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'languages' OR
            jsonb_array_length(p_filter->'languages') = 0 OR
            s.language ->> 'primary_language' IN (SELECT jsonb_array_elements_text(p_filter->'languages'))
        )
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'politicalSpectrum' OR
            (
                CASE
                    WHEN p_filter->>'politicalSpectrum' = 'left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -1.0 AND -0.7
                    WHEN p_filter->>'politicalSpectrum' = 'center-left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.7 AND -0.3
                    WHEN p_filter->>'politicalSpectrum' = 'center' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.3 AND 0.3
                    WHEN p_filter->>'politicalSpectrum' = 'center-right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.3 AND 0.7
                    WHEN p_filter->>'politicalSpectrum' = 'right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.7 AND 1.0
                    ELSE TRUE
                END
            )
        )
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'labels' OR
            jsonb_array_length(p_filter->'labels') = 0 OR
            EXISTS (
                SELECT 1
                FROM snippet_labels sl
                WHERE sl.snippet = s.id
                AND sl.label IN (
                    SELECT (jsonb_array_elements_text(p_filter->'labels'))::UUID
                )
            )
        )
        AND (trimmed_search_term = '' OR smi.id IS NOT NULL)
    ),
    total_count_cte AS (
        SELECT COUNT(*) AS cnt FROM filtered_snippets
    ),
    paginated_ids AS (
        SELECT id
        FROM filtered_snippets fs
        ORDER BY
            CASE
                WHEN p_order_by = 'upvotes' THEN fs.upvote_count + fs.like_count
                WHEN p_order_by = 'comments' THEN fs.comment_count
                WHEN p_order_by = 'activities' THEN
                    CASE WHEN fs.user_last_activity IS NULL THEN 0 ELSE EXTRACT(EPOCH FROM fs.user_last_activity) END
            END DESC,
            fs.recorded_at DESC
        LIMIT page_size
        OFFSET page * page_size
    ),
    label_summary AS (
        SELECT
            l.id,
            CASE WHEN p_language = 'spanish' THEN l.text_spanish ELSE l.text END AS text,
            sl.upvote_count,
            lu.id IS NOT NULL AS upvoted_by_me,
            sl.snippet AS snippet_id
        FROM snippet_labels sl
        JOIN labels l ON l.id = sl.label
        LEFT JOIN label_upvotes lu ON lu.snippet_label = sl.id AND lu.upvoted_by = current_user_id
        WHERE sl.snippet IN (SELECT id FROM paginated_ids)
    ),
    paginated_snippets AS (
        SELECT
            s.id,
            s.recorded_at,
            s.user_last_activity,
            s.duration,
            s.start_time,
            s.end_time,
            s.file_path,
            s.file_size,
            s.political_leaning,
            CASE
                WHEN p_language = 'spanish' THEN s.title ->> 'spanish'
                ELSE s.title ->> 'english'
            END AS title,
            CASE
                WHEN p_language = 'spanish' THEN s.summary ->> 'spanish'
                ELSE s.summary ->> 'english'
            END AS summary,
            CASE
                WHEN p_language = 'spanish' THEN s.explanation ->> 'spanish'
                ELSE s.explanation ->> 'english'
            END AS explanation,
            s.confidence_scores,
            s.language,
            s.context,
            s.upvote_count,
            s.comment_count,
            jsonb_build_object(
                'id', a.id,
                'radio_station_name', a.radio_station_name,
                'radio_station_code', a.radio_station_code,
                'location_state', a.location_state,
                'location_city', a.location_city
            ) AS audio_file,
            us.id IS NOT NULL AS starred_by_user,
            ul.value AS user_like_status,
            uhs.snippet IS NOT NULL AS hidden,
            COALESCE(s.like_count, 0) AS like_count,
            COALESCE(s.dislike_count, 0) AS dislike_count,
            COALESCE(ld.labels, '[]'::jsonb) AS labels
        FROM paginated_ids p
        JOIN snippets s ON s.id = p.id
        LEFT JOIN audio_files a ON s.audio_file = a.id
        LEFT JOIN user_star_snippets us ON us.snippet = s.id AND us."user" = current_user_id
        LEFT JOIN user_like_snippets ul ON ul.snippet = s.id AND ul."user" = current_user_id
        LEFT JOIN user_hide_snippets uhs ON uhs.snippet = s.id
        LEFT JOIN (
            SELECT
                snippet_id,
                jsonb_agg(
                    jsonb_build_object(
                        'id', id,
                        'text', text,
                        'upvote_count', upvote_count,
                        'upvoted_by_me', upvoted_by_me
                    )
                ) as labels
            FROM label_summary
            GROUP BY snippet_id
        ) ld ON p.id = ld.snippet_id
        ORDER BY
            CASE
                WHEN p_order_by = 'upvotes' THEN s.upvote_count + COALESCE(s.like_count, 0)
                WHEN p_order_by = 'comments' THEN s.comment_count
                WHEN p_order_by = 'activities' THEN
                    CASE
                        WHEN s.user_last_activity IS NULL THEN 0
                        ELSE EXTRACT(EPOCH FROM s.user_last_activity)
                    END
            END DESC,
            s.recorded_at DESC
    )
    SELECT
        jsonb_agg(
            jsonb_build_object(
                'id', ps.id,
                'recorded_at', ps.recorded_at,
                'user_last_activity', ps.user_last_activity,
                'duration', ps.duration,
                'start_time', ps.start_time,
                'end_time', ps.end_time,
                'file_path', ps.file_path,
                'file_size', ps.file_size,
                'political_leaning', ps.political_leaning,
                'title', ps.title,
                'summary', ps.summary,
                'explanation', ps.explanation,
                'confidence_scores', ps.confidence_scores,
                'language', ps.language,
                'context', ps.context,
                'labels', ps.labels,
                'audio_file', ps.audio_file,
                'starred_by_user', ps.starred_by_user,
                'user_like_status', ps.user_like_status,
                'hidden', ps.hidden,
                'like_count', ps.like_count,
                'dislike_count', ps.dislike_count
            )
        ),
        (SELECT cnt FROM total_count_cte)
    INTO result, total_count
    FROM paginated_snippets ps;

    total_pages := CEIL(total_count::FLOAT / page_size);

    RETURN jsonb_build_object(
        'num_of_snippets', total_count,
        'snippets', COALESCE(result, '[]'::jsonb),
        'current_page', page,
        'page_size', page_size,
        'total_pages', total_pages
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_snippets_debug_like_count(p_language text, p_filter jsonb, page integer, page_size integer, p_order_by text, p_search_term text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    current_user_id UUID;
    result jsonb;
    total_count INTEGER;
    total_pages INTEGER;
    user_roles TEXT[];
    user_is_admin BOOLEAN;
    trimmed_search_term TEXT := TRIM(p_search_term); -- Trim the search term here
BEGIN
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    SELECT array_agg(r.name) INTO user_roles
    FROM public.user_roles ur
    JOIN public.roles r ON ur.role = r.id
    WHERE ur."user" = current_user_id;

    user_is_admin := COALESCE('admin' = ANY(user_roles), FALSE);

    WITH
    -- like_summary AS (
    --     SELECT
    --         snippet,
    --         COUNT(*) FILTER (WHERE value = 1) AS likes,
    --         COUNT(*) FILTER (WHERE value = -1) AS dislikes
    --     FROM user_like_snippets
    --     GROUP BY snippet
    -- ),
    filtered_snippets AS (
        SELECT
            s.id,
            s.recorded_at,
            s.user_last_activity,
            s.duration,
            s.start_time,
            s.end_time,
            s.file_path,
            s.file_size,
            s.political_leaning,
            CASE
                WHEN p_language = 'spanish' THEN s.title ->> 'spanish'
                ELSE s.title ->> 'english'
            END AS title,
            CASE
                WHEN p_language = 'spanish' THEN s.summary ->> 'spanish'
                ELSE s.summary ->> 'english'
            END AS summary,
            CASE
                WHEN p_language = 'spanish' THEN s.explanation ->> 'spanish'
                ELSE s.explanation ->> 'english'
            END AS explanation,
            s.confidence_scores,
            s.language,
            s.context,
            s.upvote_count,
            s.comment_count,
            jsonb_build_object(
                'id', a.id,
                'radio_station_name', a.radio_station_name,
                'radio_station_code', a.radio_station_code,
                'location_state', a.location_state,
                'location_city', a.location_city
            ) AS audio_file,
            us.id IS NOT NULL AS starred_by_user,
            ul.value AS user_like_status,
            uhs.snippet IS NOT NULL AS hidden,
            lk.likes AS like_count,
            lk.dislikes AS dislike_count
        FROM snippets s
        LEFT JOIN audio_files a ON s.audio_file = a.id
        -- LEFT JOIN like_summary lk ON lk.snippet = s.id
        LEFT JOIN user_star_snippets us ON us.snippet = s.id AND us."user" = current_user_id
        LEFT JOIN user_like_snippets ul ON ul.snippet = s.id AND ul."user" = current_user_id
        LEFT JOIN user_hide_snippets uhs ON uhs.snippet = s.id
        CROSS JOIN LATERAL (
            SELECT
                COUNT(*) FILTER (WHERE value = 1) AS likes,
                COUNT(*) FILTER (WHERE value = -1) AS dislikes
            FROM user_like_snippets uls
            WHERE uls.snippet = s.id
        ) lk
        WHERE s.status = 'Processed' AND (s.confidence_scores->>'overall')::INTEGER >= 95
        AND (
            -- If user is admin, show all snippets (including hidden ones)
            -- If user is not admin, only show non-hidden snippets
            user_is_admin OR
            uhs.snippet IS NULL
        )
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'languages' OR
            jsonb_array_length(p_filter->'languages') = 0 OR
            s.language ->> 'primary_language' IN (SELECT jsonb_array_elements_text(p_filter->'languages'))
        )
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'states' OR
            jsonb_array_length(p_filter->'states') = 0 OR
            a.location_state IN (SELECT jsonb_array_elements_text(p_filter->'states'))
        )
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'sources' OR
            jsonb_array_length(p_filter->'sources') = 0 OR
            a.radio_station_code IN (SELECT jsonb_array_elements_text(p_filter->'sources'))
        )
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'politicalSpectrum' OR
            (
                CASE
                    WHEN p_filter->>'politicalSpectrum' = 'left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -1.0 AND -0.7
                    WHEN p_filter->>'politicalSpectrum' = 'center-left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.7 AND -0.3
                    WHEN p_filter->>'politicalSpectrum' = 'center' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.3 AND 0.3
                    WHEN p_filter->>'politicalSpectrum' = 'center-right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.3 AND 0.7
                    WHEN p_filter->>'politicalSpectrum' = 'right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.7 AND 1.0
                    ELSE TRUE
                END
            )
        )
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'labeledBy' OR
            (
                CASE
                    WHEN jsonb_array_length(p_filter->'labeledBy') = 0 THEN TRUE
                    ELSE (
                        CASE
                            WHEN (
                                p_filter->'labeledBy' ? 'by_me' AND
                                p_filter->'labeledBy' ? 'by_others'
                            ) THEN
                                EXISTS (
                                    SELECT 1
                                    FROM label_upvotes lu
                                    JOIN snippet_labels sl ON lu.snippet_label = sl.id
                                    WHERE sl.snippet = s.id
                                )
                            WHEN p_filter->'labeledBy' ? 'by_me' THEN
                                EXISTS (
                                    SELECT 1
                                    FROM label_upvotes lu
                                    JOIN snippet_labels sl ON lu.snippet_label = sl.id
                                    WHERE sl.snippet = s.id
                                    AND lu.upvoted_by = current_user_id
                                )
                            WHEN p_filter->'labeledBy' ? 'by_others' THEN
                                EXISTS (
                                    SELECT 1
                                    FROM label_upvotes lu
                                    JOIN snippet_labels sl ON lu.snippet_label = sl.id
                                    WHERE sl.snippet = s.id
                                    AND lu.upvoted_by != current_user_id
                                )
                            ELSE FALSE
                        END
                    )
                END
            )
        )
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'starredBy' OR
            (
                CASE
                    WHEN jsonb_array_length(p_filter->'starredBy') = 0 THEN TRUE
                    ELSE (
                        CASE
                            WHEN (
                                p_filter->'starredBy' ? 'by_me' AND
                                p_filter->'starredBy' ? 'by_others'
                            ) THEN
                                EXISTS (
                                    SELECT 1
                                    FROM user_star_snippets uss
                                    WHERE uss.snippet = s.id
                                )
                            WHEN p_filter->'starredBy' ? 'by_me' THEN
                                EXISTS (
                                    SELECT 1
                                    FROM user_star_snippets uss
                                    WHERE uss.snippet = s.id
                                    AND uss."user" = current_user_id
                                )
                            WHEN p_filter->'starredBy' ? 'by_others' THEN
                                EXISTS (
                                    SELECT 1
                                    FROM user_star_snippets uss
                                    WHERE uss.snippet = s.id
                                    AND uss."user" != current_user_id
                                )
                            ELSE FALSE
                        END
                    )
                END
            )
        )
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'labels' OR
            jsonb_array_length(p_filter->'labels') = 0 OR
            EXISTS (
                SELECT 1
                FROM snippet_labels sl
                WHERE sl.snippet = s.id
                AND sl.label IN (
                    SELECT (jsonb_array_elements_text(p_filter->'labels'))::UUID
                )
            )
        )
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'upvotedBy' OR
            (
                CASE
                    WHEN jsonb_array_length(p_filter->'upvotedBy') = 0 THEN TRUE
                    ELSE (
                        CASE
                            WHEN (
                                p_filter->'upvotedBy' ? 'by_me' AND
                                p_filter->'upvotedBy' ? 'by_others'
                            ) THEN
                                EXISTS (
                                    SELECT 1
                                    FROM label_upvotes lu
                                    WHERE lu.snippet_label IN (
                                        SELECT id FROM snippet_labels WHERE snippet = s.id
                                    )
                                )
                            WHEN p_filter->'upvotedBy' ? 'by_me' THEN
                                EXISTS (
                                    SELECT 1
                                    FROM label_upvotes lu
                                    WHERE lu.snippet_label IN (
                                        SELECT id FROM snippet_labels WHERE snippet = s.id
                                    )
                                    AND lu.upvoted_by = current_user_id
                                )
                            WHEN p_filter->'upvotedBy' ? 'by_others' THEN
                                EXISTS (
                                    SELECT 1
                                    FROM label_upvotes lu
                                    WHERE lu.snippet_label IN (
                                        SELECT id FROM snippet_labels WHERE snippet = s.id
                                    )
                                    AND lu.upvoted_by != current_user_id
                                )
                            ELSE FALSE
                        END
                    )
                END
            )
        )
        AND (
            trimmed_search_term = '' OR (
                ((s.title ->> 'english') || ' ' || (s.title ->> 'spanish')) &@ trimmed_search_term
                OR ((s.explanation ->> 'english') || ' ' || (s.explanation ->> 'spanish')) &@ trimmed_search_term
                OR ((s.summary ->> 'english') || ' ' || (s.summary ->> 'spanish')) &@ trimmed_search_term
                OR s.transcription &@ trimmed_search_term                 
                OR s.translation &@ trimmed_search_term
            )
        )
    ),
    paginated_snippets AS (
        SELECT fs.*, COUNT(*) OVER() AS num_of_snippets
        FROM filtered_snippets fs
        ORDER BY
            CASE
                WHEN p_order_by = 'upvotes' THEN fs.upvote_count + fs.like_count
                WHEN p_order_by = 'comments' THEN fs.comment_count
                WHEN p_order_by = 'activities' THEN
                    CASE
                        WHEN fs.user_last_activity IS NULL THEN 0
                        ELSE EXTRACT(EPOCH FROM fs.user_last_activity)
                    END
            END DESC,
            fs.recorded_at DESC -- Default for all other cases, including p_order_by = 'latest'
        LIMIT page_size
        OFFSET page * page_size
    ),
    label_summary AS (
        SELECT
            l.id,
            CASE
                WHEN p_language = 'spanish' THEN l.text_spanish
                ELSE l.text
            END AS text,
            COALESCE(lu.upvote_count, 0) AS upvote_count,
            COALESCE(lu.upvoted_by_me, FALSE) AS upvoted_by_me,
            sl.snippet AS snippet_id
        FROM snippet_labels sl
        JOIN labels l ON l.id = sl.label
        LEFT JOIN (
            SELECT
                snippet_label,
                COUNT(*) AS upvote_count,
                BOOL_OR(upvoted_by = current_user_id) AS upvoted_by_me
            FROM label_upvotes lu
            GROUP BY snippet_label
        ) lu ON lu.snippet_label = sl.id
        WHERE sl.snippet IN (SELECT id FROM paginated_snippets)
    ),
    snippets_page_with_labels_per_snippet AS (
        SELECT ps.*, ld.labels
        FROM paginated_snippets ps
        LEFT JOIN (
            SELECT
                snippet_id,
                jsonb_agg(
                    jsonb_build_object(
                        'id', id,
                        'text', text,
                        'upvote_count', upvote_count,
                        'upvoted_by_me', upvoted_by_me
                    )
                ) as labels
            FROM label_summary
            GROUP BY snippet_id
        ) ld ON ps.id = ld.snippet_id
        ORDER BY
            CASE
                WHEN p_order_by = 'upvotes' THEN ps.upvote_count + ps.like_count
                WHEN p_order_by = 'comments' THEN ps.comment_count
                WHEN p_order_by = 'activities' THEN
                    CASE
                        WHEN ps.user_last_activity IS NULL THEN 0
                        ELSE EXTRACT(EPOCH FROM ps.user_last_activity)
                    END
            END DESC,
            ps.recorded_at DESC -- Default for all other cases, including p_order_by = 'latest'
    )
    SELECT
        jsonb_agg(
            jsonb_build_object(
                'id', sp.id,
                'recorded_at', sp.recorded_at,
                'user_last_activity', sp.user_last_activity,
                'duration', sp.duration,
                'start_time', sp.start_time,
                'end_time', sp.end_time,
                'file_path', sp.file_path,
                'file_size', sp.file_size,
                'political_leaning', sp.political_leaning,
                'title', sp.title,
                'summary', sp.summary,
                'explanation', sp.explanation,
                'confidence_scores', sp.confidence_scores,
                'language', sp.language,
                'context', sp.context,
                'labels', sp.labels,
                'audio_file', sp.audio_file,
                'starred_by_user', sp.starred_by_user,
                'user_like_status', sp.user_like_status,
                'hidden', sp.hidden,
                'like_count', sp.like_count,
                'dislike_count', sp.dislike_count
            )
        ),
        MAX(sp.num_of_snippets)
    INTO result, total_count
    FROM snippets_page_with_labels_per_snippet sp;

    total_pages := CEIL(total_count::FLOAT / page_size);

    RETURN jsonb_build_object(
        'num_of_snippets', total_count,
        'snippets', COALESCE(result, '[]'::jsonb),
        'current_page', page,
        'page_size', page_size,
        'total_pages', total_pages
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_snippets_preview(p_language text, p_filter jsonb, page integer, page_size integer, p_order_by text, p_search_term text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    result jsonb;
    total_count INTEGER;
    total_pages INTEGER;
    user_roles TEXT[];
    user_is_admin BOOLEAN;
    trimmed_search_term TEXT := TRIM(p_search_term);
BEGIN
    -- Get current user and validate
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Check admin status
    SELECT array_agg(r.name) INTO user_roles
    FROM public.user_roles ur
    JOIN public.roles r ON ur.role = r.id
    WHERE ur."user" = current_user_id;
    user_is_admin := COALESCE('admin' = ANY(user_roles), FALSE);

    -- Create temporary table with only preview data
    CREATE TEMP TABLE filtered_snippets AS
        SELECT
            s.id,
            s.recorded_at,
            s.start_time,
            s.file_path,
            CASE
                WHEN p_language = 'spanish' THEN s.title ->> 'spanish'
                ELSE s.title ->> 'english'
            END AS title,
            CASE
                WHEN p_language = 'spanish' THEN s.summary ->> 'spanish'
                ELSE s.summary ->> 'english'
            END AS summary,
            (get_snippet_labels(s.id, p_language) -> 'labels') AS labels,
            CASE
                WHEN us.id IS NOT NULL THEN true
                ELSE false
            END AS starred_by_user,
            ul.value AS user_like_status,
            like_counts.likes AS like_count,
            like_counts.dislikes AS dislike_count,
            uhs.snippet IS NOT NULL AS hidden
        FROM snippets s
        LEFT JOIN audio_files a ON s.audio_file = a.id
        LEFT JOIN user_star_snippets us ON us.snippet = s.id AND us."user" = current_user_id
        LEFT JOIN user_like_snippets ul ON ul.snippet = s.id AND ul."user" = current_user_id
        LEFT JOIN user_hide_snippets uhs ON uhs.snippet = s.id
        CROSS JOIN LATERAL (
            SELECT
                COUNT(*) FILTER (WHERE value = 1) AS likes,
                COUNT(*) FILTER (WHERE value = -1) AS dislikes
            FROM user_like_snippets uls
            WHERE uls.snippet = s.id
        ) like_counts
        WHERE s.status = 'Processed' 
        AND (s.confidence_scores->>'overall')::INTEGER >= 95
        AND (
            user_is_admin OR 
            NOT EXISTS (
                SELECT 1 FROM user_hide_snippets uhs 
                WHERE uhs.snippet = s.id
            )
        )
        AND (
            trimmed_search_term = '' OR (
                ((s.title ->> 'english') || ' ' || (s.title ->> 'spanish')) &@ trimmed_search_term
                OR ((s.summary ->> 'english') || ' ' || (s.summary ->> 'spanish')) &@ trimmed_search_term
            )
        )
        ORDER BY 
            CASE
                WHEN p_order_by = 'upvotes' THEN s.upvote_count + s.like_count
                WHEN p_order_by = 'comments' THEN s.comment_count 
                WHEN p_order_by = 'activities' THEN 
                    CASE 
                        WHEN s.user_last_activity IS NULL THEN 0
                        ELSE EXTRACT(EPOCH FROM s.user_last_activity)
                    END
                ELSE EXTRACT(EPOCH FROM s.recorded_at)
            END DESC,
            s.recorded_at DESC;
        
    -- Get total count and paginate
    SELECT COUNT(*) INTO total_count
    FROM filtered_snippets;

    SELECT jsonb_agg(fs.*) INTO result
    FROM (
        SELECT * FROM filtered_snippets
        LIMIT page_size
        OFFSET page * page_size
    ) fs;

    DROP TABLE filtered_snippets;

    total_pages := CEIL(total_count::FLOAT / page_size);

    RETURN jsonb_build_object(
        'num_of_snippets', total_count,
        'snippets', COALESCE(result, '[]'::jsonb),
        'current_page', page,
        'page_size', page_size,
        'total_pages', total_pages
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_snippets_with_recent_dislikes(p_since_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_exclude_validated boolean DEFAULT true, p_limit integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    result JSONB;
BEGIN
    WITH dislike_counts AS (
        SELECT
            uls.snippet,
            COUNT(*) AS dislike_count
        FROM user_like_snippets uls
        WHERE uls.value = -1
          AND (p_since_date IS NULL OR uls.created_at >= p_since_date)
        GROUP BY uls.snippet
    ),
    filtered_snippets AS (
        SELECT dc.snippet, dc.dislike_count
        FROM dislike_counts dc
        WHERE NOT p_exclude_validated
            OR NOT EXISTS (
                SELECT 1
                FROM snippet_feedback_validation_results sfvr
                WHERE sfvr.snippet = dc.snippet
            )
    ),
    limited_snippets AS (
        SELECT
            s.id,
            s.recorded_at,
            s.transcription,
            s.translation,
            s.title,
            s.summary,
            s.explanation,
            s.disinformation_categories,
            s.confidence_scores,
            s.audio_file,
            fs.dislike_count
        FROM filtered_snippets fs
        JOIN snippets s ON s.id = fs.snippet
        ORDER BY fs.dislike_count DESC, s.recorded_at DESC
        LIMIT p_limit
    ),
    snippet_labels_agg AS (
        SELECT
            sl.snippet,
            jsonb_agg(
                jsonb_build_object(
                    'text', l.text,
                    'created_at', sl.created_at,
                    'upvote_count', sl.upvote_count
                )
            ) AS labels
        FROM snippet_labels sl
        JOIN labels l ON l.id = sl.label
        WHERE sl.snippet IN (SELECT id FROM limited_snippets)
          AND sl.applied_by IS NOT NULL
        GROUP BY sl.snippet
    ),
    comments_agg AS (
        SELECT
            c.room_id AS snippet,
            jsonb_agg(
                jsonb_build_object(
                    'body', c.body,
                    'comment_at', c.comment_at
                )
                ORDER BY c.comment_at ASC
            ) AS comments
        FROM comments c
        WHERE c.room_id IN (SELECT id FROM limited_snippets)
        GROUP BY c.room_id
    )
    SELECT COALESCE(
        jsonb_agg(
            to_jsonb(ls) || jsonb_build_object(
                'audio_file', jsonb_build_object(
                    'radio_station_name', af.radio_station_name,
                    'radio_station_code', af.radio_station_code,
                    'location_state', af.location_state
                ),
                'labels', COALESCE(sla.labels, '[]'::jsonb),
                'comments', COALESCE(ca.comments, '[]'::jsonb)
            )
            ORDER BY ls.dislike_count DESC, ls.recorded_at DESC
        ),
        '[]'::jsonb
    )
    INTO result
    FROM limited_snippets ls
    LEFT JOIN audio_files af ON af.id = ls.audio_file
    LEFT JOIN snippet_labels_agg sla ON sla.snippet = ls.id
    LEFT JOIN comments_agg ca ON ca.snippet = ls.id;

    RETURN result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_statistics(from_time timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_role text;
    result jsonb;
BEGIN
    -- Ensure that the caller has valid permission to call this function
    current_user_role := auth.role();
    IF current_user_role NOT IN ('postgres', 'service_role') THEN
        RAISE EXCEPTION 'Access denied. Current user role: %', current_user_role;
    END IF;

    -- Count the number of audio files processed since 'from_time'
    create temp table processed_audio_files_count AS
    select count(*)
    from public.audio_files
    where status <> 'New'
    and updated_at >= from_time;

    -- Classify the audio files based on their status
    create temp table audio_files_by_status as
    select count(*), status
    from public.audio_files
    where status <> 'New'
    and updated_at >= from_time
    group by status;

    -- Retrieve the audio files whose status is 'Processing'
    create temp table processing_audio_files AS
    select id
    from public.audio_files
    where status = 'Processing'
    and updated_at >= from_time;

    -- Classify the audio files based on their error_message
    create temp table audio_files_by_error_message as
    select count(*), error_message
    from public.audio_files
    where status <> 'New'
    and updated_at >= from_time
    group by error_message;

    -- Count the number of stage_1_llm_responses inserted since 'from_time'
    create temp table new_stage_1_llm_responses_count AS
    select count(*)
    from public.stage_1_llm_responses
    where updated_at >= from_time;

    -- Detect duplications in stage_1_llm_responses table
    create temp table stage_1_llm_responses_duplication_count AS
    select count(*)
    from (
        select count(id), audio_file
        from public.stage_1_llm_responses
        where updated_at >= from_time
        group by audio_file
    ) as t
    where t.COUNT > 1;
    --
    create temp table stage_1_llm_responses_duplication AS
    select id, audio_file, initial_detection_result, detection_result, status, error_message
    from public.stage_1_llm_responses
    where audio_file in (
        select audio_file
        from public.stage_1_llm_responses
        where updated_at >= from_time
        group by audio_file
        having count(id) > 1
    )
    order by audio_file;

    -- Classify the stage_1_llm_responses based on their status
    create temp table stage_1_llm_responses_by_status AS
    select count(*), status
    from public.stage_1_llm_responses
    where updated_at >= from_time
    group by status;

    -- Classify the stage_1_llm_responses based on their error_message
    create temp table stage_1_llm_responses_by_error_message AS
    select count(*), array_agg(id::text) as ids, error_message
    from public.stage_1_llm_responses
    where updated_at >= from_time
    group by error_message;

    -- Classify the stage_1_llm_responses based on the transcriptor
    create temp table stage_1_llm_responses_by_transcriptor AS
    select count(*), transcriptor
    from public.stage_1_llm_responses
    where updated_at >= from_time
    group by transcriptor;

    -- Count the number of stage_1_llm_responses which contain disinformation during initial detection phase
    create temp table stage_1_llm_responses_count_initial_detected AS
    select count(*)
    from public.stage_1_llm_responses
    where updated_at >= from_time
    and initial_detection_result <> '{"flagged_snippets":[]}';

    -- Count the number of stage_1_llm_responses which do not contain disinformation during initial detection phase
    create temp table stage_1_llm_responses_count_initial_no_detected AS
    select count(*)
    from public.stage_1_llm_responses
    where updated_at >= from_time
    and initial_detection_result = '{"flagged_snippets":[]}';

    -- Count the number of stage_1_llm_responses which contain disinformation during main detection phase
    create temp table stage_1_llm_responses_count_main_detected AS
    select count(*)
    from public.stage_1_llm_responses
    where updated_at >= from_time
    and initial_detection_result <> '{"flagged_snippets":[]}'
    and detection_result <> '{"flagged_snippets":[]}';

    -- Count the number of stage_1_llm_responses which do not contain disinformation during main detection phase
    create temp table stage_1_llm_responses_count_main_no_detected AS
    select count(*)
    from public.stage_1_llm_responses
    where updated_at >= from_time
    and initial_detection_result <> '{"flagged_snippets":[]}'
    and detection_result = '{"flagged_snippets":[]}';

    -- Count the number of snippets inserted since 'from_time'
    create temp table new_snippets_count AS
    select count(*)
    from public.snippets
    where created_at >= from_time;

    -- Count the number of snippets whose confidence score were high
    create temp table high_confidence_snippets_count AS
    select count(*)
    from public.snippets
    where created_at >= from_time
    and (confidence_scores->>'overall')::integer >= 95;

    -- Count the number of snippets whose confidence score were low
    create temp table low_confidence_snippets_count AS
    select count(*)
    from public.snippets
    where created_at >= from_time
    and (confidence_scores->>'overall')::integer < 95;

    -- Classify the snippets based on their status
    create temp table snippets_by_status AS
    select count(*), status
    from public.snippets
    where created_at >= from_time
    group by status;

    -- Classify the snippets based on their error_message
    create temp table snippets_by_error_message AS
    select count(*), array_agg(id::text) as ids, error_message
    from public.snippets
    where created_at >= from_time
    group by error_message;

    -- Combine the results
    select json_build_object(
    'audio_files', json_build_object(
        'count', (select * from processed_audio_files_count),
        'by_status', (
        select json_agg(json_build_object(
            'count', COUNT,
            'status', status,
            'ids', case
                when status = 'Processing' then (select json_agg(id) from processing_audio_files)
                else null
            end
        )) from audio_files_by_status
        ),
        'by_error_message', (
        select json_agg(json_build_object(
            'count', COUNT,
            'error_message', error_message
        )) from audio_files_by_error_message
        )
    ),
    'stage_1_llm_responses', (select json_build_object(
        'count', (select * from new_stage_1_llm_responses_count),
        'count_initial', (select json_build_object(
        'detected', (select * from stage_1_llm_responses_count_initial_detected),
        'no_detected', (select * from stage_1_llm_responses_count_initial_no_detected)
        )),
        'count_main', (select json_build_object(
        'detected', (select * from stage_1_llm_responses_count_main_detected),
        'no_detected', (select * from stage_1_llm_responses_count_main_no_detected)
        )),    
        'duplicate', (select json_build_object(
        'count', (select * from stage_1_llm_responses_duplication_count),
        'llm_responses', coalesce((select json_agg(json_build_object(
            'id', id,
            'audio_file', audio_file,
            'initial_detection_result', initial_detection_result,
            'detection_result', detection_result,
            'status', status,
            'error_message', error_message
        )) from stage_1_llm_responses_duplication), '[]'::json)
        )),
        'by_status', (
            select json_agg(json_build_object(
                'count', COUNT,
                'status', status
            )) from stage_1_llm_responses_by_status
        ),
        'by_error_message', (
            select json_agg(json_build_object(
                'count', COUNT,
                'error_message', error_message,
                'ids', case when error_message is null then null else ids end
            )) from stage_1_llm_responses_by_error_message
        ),
        'by_transcriptor', (
            select json_agg(json_build_object(
                'count', COUNT,
                'transcriptor', transcriptor
            )) from stage_1_llm_responses_by_transcriptor
        )
    )),
    'snippets', (select json_build_object(
        'count', (select * from new_snippets_count),
        'high_confidence_count', (select * from high_confidence_snippets_count),
        'low_confidence_count', (select * from low_confidence_snippets_count),
        'by_status', (
        select json_agg(json_build_object(
            'count', COUNT,
            'status', status
        )) from snippets_by_status
        ),
        'by_error_message', (
        select json_agg(json_build_object(
            'count', COUNT,
            'error_message', error_message,
            'ids', case when error_message is null then null else ids end
        )) from snippets_by_error_message
        )    
    )),
    'global', (select json_build_object(
        'audio_files', (select json_build_object(
            'total', (select count(*) from public.audio_files),
            'new', (select count(*) from public.audio_files where status = 'New'),
            'processing', (select count(*) from public.audio_files where status = 'Processing'),
            'processed', (select count(*) from public.audio_files where status = 'Processed'),
            'error', (select count(*) from public.audio_files where status = 'Error')
        )),
        'stage_1_llm_responses', (select json_build_object(
            'total', (select count(*) from public.stage_1_llm_responses),
            'new', (select count(*) from public.stage_1_llm_responses where status = 'New'),
            'processing', (select count(*) from public.stage_1_llm_responses where status = 'Processing'),
            'processed', (select count(*) from public.stage_1_llm_responses where status = 'Processed'),
            'error', (select count(*) from public.stage_1_llm_responses where status = 'Error')
        )),
        'snippets', (select json_build_object(
            'total', (select count(*) from public.snippets),
            'new', (select count(*) from public.snippets where status = 'New'),
            'processing', (select count(*) from public.snippets where status = 'Processing'),
            'processed', (select count(*) from public.snippets where status = 'Processed'),
            'error', (select count(*) from public.snippets where status = 'Error'),
            'high_score', (select count(*) from public.snippets where (confidence_scores->>'overall')::integer >= 95 and status = 'Processed'),
            'low_score', (select count(*) from public.snippets where (confidence_scores->>'overall')::integer < 95 and status = 'Processed')
        ))
    ))
    ) into result;

    RETURN COALESCE(result, '{}'::jsonb);
END; $function$;

CREATE OR REPLACE FUNCTION public.get_topic_details(p_topic_id uuid, p_timespan text DEFAULT '7d'::text, p_filter jsonb DEFAULT NULL::jsonb, p_language text DEFAULT 'english'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  current_user_id UUID;
  v_start_time TIMESTAMP WITH TIME ZONE;
  v_prev_start_time TIMESTAMP WITH TIME ZONE;
  v_prev_end_time TIMESTAMP WITH TIME ZONE;
  v_interval INTERVAL;
  v_topic_text TEXT;
  v_current_count INTEGER;
  v_prev_count INTEGER;
  v_change_percent NUMERIC;
  v_sparkline INTEGER[];
  v_sparkline_labels TEXT[];
  v_bucket_interval INTERVAL;
  v_num_buckets INTEGER;
  v_bucket_start TIMESTAMP WITH TIME ZONE;
  v_bucket_count INTEGER;
  v_bucket_label TEXT;
BEGIN
  -- Check if the user is authenticated
  current_user_id := auth.uid();
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'Only logged-in users can call this function';
  END IF;

  -- Set time boundaries based on timespan
  CASE p_timespan
    WHEN '24h' THEN
      v_interval := INTERVAL '24 hours';
      v_bucket_interval := INTERVAL '2 hours';
      v_num_buckets := 12;
    WHEN '7d' THEN
      v_interval := INTERVAL '7 days';
      v_bucket_interval := INTERVAL '1 day';
      v_num_buckets := 7;
    WHEN '30d' THEN
      v_interval := INTERVAL '30 days';
      v_bucket_interval := INTERVAL '3 days';
      v_num_buckets := 10;
    WHEN '90d' THEN
      v_interval := INTERVAL '90 days';
      v_bucket_interval := INTERVAL '9 days';
      v_num_buckets := 10;
    WHEN 'all' THEN
      v_interval := INTERVAL '365 days';
      v_bucket_interval := INTERVAL '30 days';
      v_num_buckets := 12;
    ELSE
      v_interval := INTERVAL '7 days';
      v_bucket_interval := INTERVAL '1 day';
      v_num_buckets := 7;
  END CASE;

  v_start_time := NOW() - v_interval;
  v_prev_end_time := v_start_time;
  v_prev_start_time := v_prev_end_time - v_interval;

  -- Get topic text
  SELECT 
    CASE WHEN p_language = 'spanish' AND text_spanish IS NOT NULL THEN text_spanish ELSE text END
  INTO v_topic_text
  FROM labels
  WHERE id = p_topic_id;

  IF v_topic_text IS NULL THEN
    RETURN jsonb_build_object('timespan', p_timespan, 'topic', NULL);
  END IF;

  -- Get current period count using same filter logic as get_trending_topics
  SELECT COUNT(DISTINCT sl.snippet)
  INTO v_current_count
  FROM snippet_labels sl
  JOIN snippets s ON s.id = sl.snippet
  LEFT JOIN audio_files a ON s.audio_file = a.id
  WHERE sl.label = p_topic_id
    AND s.status = 'Processed'
    AND (s.confidence_scores->>'overall')::INTEGER >= 95
    AND s.recorded_at >= v_start_time
    -- Language filter
    AND (
      p_filter IS NULL OR
      NOT p_filter ? 'languages' OR
      jsonb_array_length(p_filter->'languages') = 0 OR
      s.language ->> 'primary_language' IN (SELECT jsonb_array_elements_text(p_filter->'languages'))
    )
    -- State filter
    AND (
      p_filter IS NULL OR
      NOT p_filter ? 'states' OR
      jsonb_array_length(p_filter->'states') = 0 OR
      a.location_state IN (SELECT jsonb_array_elements_text(p_filter->'states'))
    )
    -- Source filter
    AND (
      p_filter IS NULL OR
      NOT p_filter ? 'sources' OR
      jsonb_array_length(p_filter->'sources') = 0 OR
      a.radio_station_code IN (SELECT jsonb_array_elements_text(p_filter->'sources'))
    )
    -- Political spectrum filter
    AND (
      p_filter IS NULL OR
      NOT p_filter ? 'politicalSpectrum' OR
      (
        CASE
          WHEN p_filter->>'politicalSpectrum' = 'left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -1.0 AND -0.7
          WHEN p_filter->>'politicalSpectrum' = 'center-left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.7 AND -0.3
          WHEN p_filter->>'politicalSpectrum' = 'center' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.3 AND 0.3
          WHEN p_filter->>'politicalSpectrum' = 'center-right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.3 AND 0.7
          WHEN p_filter->>'politicalSpectrum' = 'right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.7 AND 1.0
          ELSE TRUE
        END
      )
    )
    -- Exclude hidden snippets
    AND NOT EXISTS (
      SELECT 1 FROM user_hide_snippets uhs WHERE uhs.snippet = s.id
    );

  -- Get previous period count (for comparison) - now includes 90d
  IF p_timespan != 'all' THEN
    SELECT COUNT(DISTINCT sl.snippet)
    INTO v_prev_count
    FROM snippet_labels sl
    JOIN snippets s ON s.id = sl.snippet
    LEFT JOIN audio_files a ON s.audio_file = a.id
    WHERE sl.label = p_topic_id
      AND s.status = 'Processed'
      AND (s.confidence_scores->>'overall')::INTEGER >= 95
      AND s.recorded_at >= v_prev_start_time
      AND s.recorded_at < v_prev_end_time
      -- Language filter
      AND (
        p_filter IS NULL OR
        NOT p_filter ? 'languages' OR
        jsonb_array_length(p_filter->'languages') = 0 OR
        s.language ->> 'primary_language' IN (SELECT jsonb_array_elements_text(p_filter->'languages'))
      )
      -- State filter
      AND (
        p_filter IS NULL OR
        NOT p_filter ? 'states' OR
        jsonb_array_length(p_filter->'states') = 0 OR
        a.location_state IN (SELECT jsonb_array_elements_text(p_filter->'states'))
      )
      -- Source filter
      AND (
        p_filter IS NULL OR
        NOT p_filter ? 'sources' OR
        jsonb_array_length(p_filter->'sources') = 0 OR
        a.radio_station_code IN (SELECT jsonb_array_elements_text(p_filter->'sources'))
      )
      -- Political spectrum filter
      AND (
        p_filter IS NULL OR
        NOT p_filter ? 'politicalSpectrum' OR
        (
          CASE
            WHEN p_filter->>'politicalSpectrum' = 'left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -1.0 AND -0.7
            WHEN p_filter->>'politicalSpectrum' = 'center-left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.7 AND -0.3
            WHEN p_filter->>'politicalSpectrum' = 'center' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.3 AND 0.3
            WHEN p_filter->>'politicalSpectrum' = 'center-right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.3 AND 0.7
            WHEN p_filter->>'politicalSpectrum' = 'right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.7 AND 1.0
            ELSE TRUE
          END
        )
      )
      -- Exclude hidden snippets
      AND NOT EXISTS (
        SELECT 1 FROM user_hide_snippets uhs WHERE uhs.snippet = s.id
      );

    -- Calculate change percent
    IF v_prev_count > 0 THEN
      v_change_percent := ROUND(((v_current_count::NUMERIC - v_prev_count::NUMERIC) / v_prev_count::NUMERIC) * 100, 1);
    ELSIF v_current_count > 0 THEN
      v_change_percent := 100;
    ELSE
      v_change_percent := 0;
    END IF;
  ELSE
    v_prev_count := 0;
    v_change_percent := 0;
  END IF;

  -- Build sparkline data
  v_sparkline := ARRAY[]::INTEGER[];
  v_sparkline_labels := ARRAY[]::TEXT[];

  FOR i IN 0..(v_num_buckets - 1) LOOP
    v_bucket_start := v_start_time + (v_bucket_interval * i);

    SELECT COUNT(DISTINCT sl.snippet)
    INTO v_bucket_count
    FROM snippet_labels sl
    JOIN snippets s ON s.id = sl.snippet
    LEFT JOIN audio_files a ON s.audio_file = a.id
    WHERE sl.label = p_topic_id
      AND s.status = 'Processed'
      AND (s.confidence_scores->>'overall')::INTEGER >= 95
      AND s.recorded_at >= v_bucket_start
      AND s.recorded_at < v_bucket_start + v_bucket_interval
      -- Language filter
      AND (
        p_filter IS NULL OR
        NOT p_filter ? 'languages' OR
        jsonb_array_length(p_filter->'languages') = 0 OR
        s.language ->> 'primary_language' IN (SELECT jsonb_array_elements_text(p_filter->'languages'))
      )
      -- State filter
      AND (
        p_filter IS NULL OR
        NOT p_filter ? 'states' OR
        jsonb_array_length(p_filter->'states') = 0 OR
        a.location_state IN (SELECT jsonb_array_elements_text(p_filter->'states'))
      )
      -- Source filter
      AND (
        p_filter IS NULL OR
        NOT p_filter ? 'sources' OR
        jsonb_array_length(p_filter->'sources') = 0 OR
        a.radio_station_code IN (SELECT jsonb_array_elements_text(p_filter->'sources'))
      )
      -- Political spectrum filter
      AND (
        p_filter IS NULL OR
        NOT p_filter ? 'politicalSpectrum' OR
        (
          CASE
            WHEN p_filter->>'politicalSpectrum' = 'left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -1.0 AND -0.7
            WHEN p_filter->>'politicalSpectrum' = 'center-left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.7 AND -0.3
            WHEN p_filter->>'politicalSpectrum' = 'center' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.3 AND 0.3
            WHEN p_filter->>'politicalSpectrum' = 'center-right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.3 AND 0.7
            WHEN p_filter->>'politicalSpectrum' = 'right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.7 AND 1.0
            ELSE TRUE
          END
        )
      )
      -- Exclude hidden snippets
      AND NOT EXISTS (
        SELECT 1 FROM user_hide_snippets uhs WHERE uhs.snippet = s.id
      );

    v_sparkline := v_sparkline || COALESCE(v_bucket_count, 0);

    -- Generate label for bucket
    CASE p_timespan
      WHEN '24h' THEN
        v_bucket_label := TO_CHAR(v_bucket_start, 'HH24:MI');
      WHEN '7d' THEN
        v_bucket_label := TO_CHAR(v_bucket_start, 'Dy');
      WHEN '30d' THEN
        v_bucket_label := TO_CHAR(v_bucket_start, 'Mon DD');
      WHEN '90d' THEN
        v_bucket_label := TO_CHAR(v_bucket_start, 'Mon DD');
      ELSE
        v_bucket_label := TO_CHAR(v_bucket_start, 'Mon YYYY');
    END CASE;

    v_sparkline_labels := v_sparkline_labels || v_bucket_label;
  END LOOP;

  RETURN jsonb_build_object(
    'timespan', p_timespan,
    'topic', jsonb_build_object(
      'id', p_topic_id,
      'text', v_topic_text,
      'count', v_current_count,
      'sparkline', v_sparkline,
      'sparklineLabels', v_sparkline_labels,
      'previousPeriodCount', v_prev_count,
      'changePercent', v_change_percent
    )
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_trending_topics(p_timespan text DEFAULT '7d'::text, p_filter jsonb DEFAULT NULL::jsonb, p_language text DEFAULT 'english'::text, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    result JSONB;
    time_start TIMESTAMPTZ;
    bucket_interval INTERVAL;
    num_buckets INTEGER;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Determine time window and bucket size based on timespan
    CASE p_timespan
        WHEN '24h' THEN
            time_start := NOW() - INTERVAL '24 hours';
            bucket_interval := INTERVAL '1 hour';
            num_buckets := 24;
        WHEN '7d' THEN
            time_start := NOW() - INTERVAL '7 days';
            bucket_interval := INTERVAL '1 day';
            num_buckets := 7;
        WHEN '30d' THEN
            time_start := NOW() - INTERVAL '30 days';
            bucket_interval := INTERVAL '1 day';
            num_buckets := 30;
        WHEN '90d' THEN
            time_start := NOW() - INTERVAL '90 days';
            bucket_interval := INTERVAL '9 days';
            num_buckets := 10;
        ELSE -- 'all' or default
            time_start := NOW() - INTERVAL '365 days';
            bucket_interval := INTERVAL '30 days';
            num_buckets := 12;
    END CASE;

    WITH
    -- Pre-compute hidden snippet IDs (small set to exclude via LEFT JOIN)
    hidden_snippets AS (
        SELECT DISTINCT snippet FROM user_hide_snippets
    ),
    -- Filter snippets based on provided filters (optimized with LEFT JOIN instead of NOT EXISTS)
    filtered_snippets AS (
        SELECT s.id, s.recorded_at
        FROM snippets s
        LEFT JOIN audio_files a ON s.audio_file = a.id
        LEFT JOIN hidden_snippets hs ON hs.snippet = s.id
        WHERE s.status = 'Processed'
        AND (s.confidence_scores->>'overall')::INTEGER >= 95
        AND s.recorded_at >= time_start
        -- Exclude hidden snippets via JOIN (faster than NOT EXISTS)
        AND hs.snippet IS NULL
        -- Language filter
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'languages' OR
            jsonb_array_length(p_filter->'languages') = 0 OR
            s.language ->> 'primary_language' IN (SELECT jsonb_array_elements_text(p_filter->'languages'))
        )
        -- State filter
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'states' OR
            jsonb_array_length(p_filter->'states') = 0 OR
            a.location_state IN (SELECT jsonb_array_elements_text(p_filter->'states'))
        )
        -- Source filter
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'sources' OR
            jsonb_array_length(p_filter->'sources') = 0 OR
            a.radio_station_code IN (SELECT jsonb_array_elements_text(p_filter->'sources'))
        )
        -- Political spectrum filter
        AND (
            p_filter IS NULL OR
            NOT p_filter ? 'politicalSpectrum' OR
            (
                CASE
                    WHEN p_filter->>'politicalSpectrum' = 'left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -1.0 AND -0.7
                    WHEN p_filter->>'politicalSpectrum' = 'center-left' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.7 AND -0.3
                    WHEN p_filter->>'politicalSpectrum' = 'center' THEN (s.political_leaning->>'score')::FLOAT BETWEEN -0.3 AND 0.3
                    WHEN p_filter->>'politicalSpectrum' = 'center-right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.3 AND 0.7
                    WHEN p_filter->>'politicalSpectrum' = 'right' THEN (s.political_leaning->>'score')::FLOAT BETWEEN 0.7 AND 1.0
                    ELSE TRUE
                END
            )
        )
    ),
    -- Get label counts from filtered snippets
    label_counts AS (
        SELECT
            l.id AS label_id,
            CASE
                WHEN p_language = 'spanish' THEN COALESCE(l.text_spanish, l.text)
                ELSE l.text
            END AS label_text,
            COUNT(DISTINCT sl.snippet) AS snippet_count
        FROM snippet_labels sl
        JOIN labels l ON sl.label = l.id
        JOIN filtered_snippets fs ON sl.snippet = fs.id
        GROUP BY l.id, l.text, l.text_spanish
        ORDER BY snippet_count DESC
        LIMIT p_limit
    ),
    -- Generate time buckets for sparkline
    time_buckets AS (
        SELECT generate_series(
            date_trunc(
                CASE WHEN p_timespan = '24h' THEN 'hour' ELSE 'day' END,
                time_start
            ),
            date_trunc(
                CASE WHEN p_timespan = '24h' THEN 'hour' ELSE 'day' END,
                NOW()
            ),
            bucket_interval
        ) AS bucket_start
    ),
    -- Get sparkline data for top labels - count snippets per bucket
    sparkline_data AS (
        SELECT
            lc.label_id,
            tb.bucket_start,
            COUNT(DISTINCT CASE
                WHEN fs.recorded_at >= tb.bucket_start
                AND fs.recorded_at < tb.bucket_start + bucket_interval
                THEN fs.id
            END) AS count
        FROM label_counts lc
        CROSS JOIN time_buckets tb
        LEFT JOIN snippet_labels sl ON sl.label = lc.label_id
        LEFT JOIN filtered_snippets fs ON sl.snippet = fs.id
        GROUP BY lc.label_id, tb.bucket_start
        ORDER BY lc.label_id, tb.bucket_start
    ),
    -- Aggregate sparkline data per label
    sparkline_agg AS (
        SELECT
            label_id,
            jsonb_agg(count ORDER BY bucket_start) AS sparkline
        FROM sparkline_data
        GROUP BY label_id
    )
    -- Build final result
    SELECT jsonb_build_object(
        'timespan', p_timespan,
        'topics', COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'id', lc.label_id,
                    'text', lc.label_text,
                    'count', lc.snippet_count,
                    'sparkline', COALESCE(sa.sparkline, '[]'::jsonb)
                )
                ORDER BY lc.snippet_count DESC
            ),
            '[]'::jsonb
        )
    ) INTO result
    FROM label_counts lc
    LEFT JOIN sparkline_agg sa ON lc.label_id = sa.label_id;

    RETURN COALESCE(result, jsonb_build_object('timespan', p_timespan, 'topics', '[]'::jsonb));
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_users()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    result jsonb;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Return specified fields of all users from the auth schema
    SELECT jsonb_agg(jsonb_build_object(
        'id', u.id,
        'email', u.email,
        'raw_user_meta_data', 
        u.raw_user_meta_data - 'iss' - 'sub' - 'email_verified' - 'phone_verified' - 'provider_id' - 'custom_claims'
    )) INTO result
    FROM auth.users u;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_users_by_emails(emails text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$ 
DECLARE 
    current_user_id UUID;
    result jsonb; 
BEGIN 
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Return specified fields of users from the auth schema based on provided emails 
    SELECT jsonb_agg(jsonb_build_object( 
        'id', u.id, 
        'email', u.email, 
        'raw_user_meta_data', u.raw_user_meta_data - 'iss' - 'sub' - 'email_verified' - 'phone_verified' - 'provider_id' - 'custom_claims'
    )) 
    INTO result 
    FROM auth.users u 
    WHERE u.email = ANY(emails); 

    RETURN COALESCE(result, '[]'::jsonb); 
END; 
$function$;

CREATE OR REPLACE FUNCTION public.get_welcome_card(p_language text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$DECLARE 
    current_user_id UUID; 
    card_data JSONB;
    actual_lang VARCHAR(5);
    lang_code VARCHAR(5);
BEGIN 
    -- Check if the user is authenticated 
    current_user_id := auth.uid(); 
    IF current_user_id IS NULL THEN 
        RAISE EXCEPTION 'Only logged-in users can call this function'; 
    END IF; 

  lang_code := CASE LOWER(p_language)
    WHEN 'english' THEN 'en'
    WHEN 'spanish' THEN 'es'
    WHEN 'french' THEN 'fr'
    ELSE NULL
  END;

  -- First try to get the requested language
  SELECT language_code
  INTO actual_lang
  FROM welcome_card
  WHERE language_code = lang_code
  LIMIT 1;
  
  -- If not found, use default language
  IF actual_lang IS NULL THEN
    SELECT language_code
    INTO actual_lang
    FROM welcome_card
    WHERE language_code = 'en'
    LIMIT 1;
  END IF;
  
  SELECT JSONB_BUILD_OBJECT(
    'id', id,
    'language', language_code,
    'title', title,
    'subtitle', subtitle,
    'features', features,
    'footer_text', footer_text,
    'contact_email', contact_email,
    'contact_text', contact_text
  )
  INTO card_data
  FROM welcome_card
  WHERE language_code = actual_lang
  LIMIT 1;
  
  RETURN card_data;
END;$function$;

CREATE OR REPLACE FUNCTION public.hide_snippet(snippet_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$ 
DECLARE 
    current_user_id UUID; 
    user_roles text[]; 
BEGIN 
    -- Check if the user is authenticated 
    current_user_id := auth.uid(); 
    IF current_user_id IS NULL THEN 
        RAISE EXCEPTION 'Only logged-in users can call this function'; 
    END IF; 

    -- Get the roles of the current user
    user_roles := get_roles(); 

    -- Check if the user has the admin role
    IF 'admin' = ANY(user_roles) THEN 
        INSERT INTO public.user_hide_snippets (snippet, "user") 
        VALUES (snippet_id, current_user_id)
        ON CONFLICT (snippet) DO NOTHING;

        RETURN jsonb_build_object('status', 'success', 'message', 'Snippet has been hidden successfully'); 
    END IF;


    RETURN jsonb_build_object('status', 'error', 'message', 'Only admin users can hide the snippet');
END; 
$function$;

CREATE OR REPLACE FUNCTION public.like_snippet(snippet_id uuid, value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE 
    current_user_id UUID; 
    liked_snippet_id UUID; 
    like_count INTEGER; 
    dislike_count INTEGER; 
BEGIN 
    -- Check if the user is authenticated 
    current_user_id := auth.uid(); 
    IF current_user_id IS NULL THEN 
        RAISE EXCEPTION 'Only logged-in users can call this function'; 
    END IF; 

    -- Ensure that value is either 0, -1 or 1 
    IF VALUE NOT IN (0, -1, 1) THEN 
        RAISE EXCEPTION 'Value must be either 0, -1, or 1'; 
    END IF; 

    -- Insert (or upsert) the record in the table user_like_snippets with the given value 
    INSERT INTO public.user_like_snippets ("user", snippet, value) 
    VALUES (current_user_id, snippet_id, value) 
    ON CONFLICT ("user", snippet) 
    DO UPDATE SET value = EXCLUDED.value 
    RETURNING id INTO liked_snippet_id; 

    -- Calculate like_count and dislike_count for the current snippet 
    SELECT 
        COUNT(*) FILTER (WHERE user_like_snippets.value = 1) AS like_count, 
        COUNT(*) FILTER (WHERE user_like_snippets.value = -1) AS dislike_count 
    INTO like_count, dislike_count
    FROM public.user_like_snippets 
    WHERE snippet = snippet_id; 

    -- Return the like_count and dislike_count along with the status 
    RETURN jsonb_build_object(
        'status', 'success',
        'id', liked_snippet_id, 
        'like_count', like_count, 
        'dislike_count', dislike_count
    ); 
END; 
$function$;

