 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
    REFRESH MATERIALIZED VIEW filter_options_cache;
END;
$function$;

CREATE OR REPLACE FUNCTION public.run_tsv_backfill()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    ctrl backfill_control%ROWTYPE;
    rows_updated INTEGER;
    remaining INTEGER;
BEGIN
    -- Get control settings
    SELECT * INTO ctrl FROM backfill_control WHERE id = 'tsv_backfill';
    
    -- Check kill switch
    IF ctrl.enabled = false THEN
        UPDATE backfill_control 
        SET status = 'paused', last_run_at = NOW()
        WHERE id = 'tsv_backfill';
        RETURN jsonb_build_object('status', 'paused', 'message', 'Backfill is disabled');
    END IF;
    
    -- Update status to running
    UPDATE backfill_control SET status = 'running', last_run_at = NOW() WHERE id = 'tsv_backfill';
    
    -- Do the backfill with configured batch size
    WITH updated AS (
        UPDATE stage_1_llm_responses
        SET tsv_transcription = to_tsvector('spanish', COALESCE(initial_transcription, ''))
        WHERE id IN (
            SELECT id FROM stage_1_llm_responses
            WHERE tsv_transcription IS NULL
            LIMIT ctrl.batch_size
        )
        RETURNING id
    )
    SELECT COUNT(*) INTO rows_updated FROM updated;
    
    -- Count remaining
    SELECT COUNT(*) INTO remaining FROM stage_1_llm_responses WHERE tsv_transcription IS NULL;
    
    -- Update control with results
    UPDATE backfill_control 
    SET rows_processed = rows_processed + rows_updated,
        status = CASE WHEN remaining = 0 THEN 'completed' ELSE 'running' END
    WHERE id = 'tsv_backfill';
    
    RETURN jsonb_build_object(
        'status', 'success',
        'rows_updated', rows_updated,
        'remaining', remaining,
        'batch_size', ctrl.batch_size
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.search_kb_entries(query_embedding extensions.vector, match_threshold double precision DEFAULT 0.75, match_count integer DEFAULT 10, candidate_multiplier integer DEFAULT 8, filter_categories text[] DEFAULT NULL::text[], reference_date timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    query_sub_embedding vector(512);
    result jsonb;
BEGIN
    -- Compute the sub-vector for the first-pass HNSW search
    query_sub_embedding := sub_vector(query_embedding, 512)::vector(512);

    WITH
    -- Stage 1: Approximate search using sub-vector HNSW index
    candidates AS (
        SELECT
            ke.id AS entry_id,
            kee.embedding
        FROM kb_entry_embeddings kee
        JOIN kb_entries ke ON ke.id = kee.kb_entry
        WHERE
            ke.status = 'active'
            AND kee.status = 'Processed'
            -- Optional category filter
            AND (filter_categories IS NULL
                 OR ke.disinformation_categories && filter_categories)
            -- Temporal relevance: exclude entries outside their valid range
            AND (ke.valid_from IS NULL OR ke.valid_from <= reference_date)
            AND (ke.valid_until IS NULL OR ke.valid_until >= reference_date)
        ORDER BY
            sub_vector(kee.embedding, 512)::vector(512) <#> query_sub_embedding ASC
        LIMIT match_count * candidate_multiplier
    ),
    -- Stage 2: Re-rank using full 3072-dim inner product
    ranked AS (
        SELECT
            c.entry_id,
            -(c.embedding <#> query_embedding) AS similarity
        FROM candidates c
        WHERE -(c.embedding <#> query_embedding) > match_threshold
        ORDER BY c.embedding <#> query_embedding ASC
        LIMIT match_count
    ),
    -- Aggregate sources per entry
    source_agg AS (
        SELECT
            ks.kb_entry,
            jsonb_agg(
                jsonb_build_object(
                    'url', ks.url,
                    'source_name', ks.source_name,
                    'source_type', ks.source_type,
                    'title', ks.title,
                    'relevant_excerpt', ks.relevant_excerpt,
                    'publication_date', ks.publication_date,
                    'relevance_to_claim', ks.relevance_to_claim
                )
            ) AS sources
        FROM kb_entry_sources ks
        WHERE ks.kb_entry IN (SELECT entry_id FROM ranked)
        GROUP BY ks.kb_entry
    ),
    -- Build final result
    final_entries AS (
        SELECT
            jsonb_build_object(
                'id', ke.id,
                'fact', ke.fact,
                'related_claim', ke.related_claim,
                'confidence_score', ke.confidence_score,
                'valid_from', ke.valid_from,
                'valid_until', ke.valid_until,
                'is_time_sensitive', ke.is_time_sensitive,
                'disinformation_categories', ke.disinformation_categories,
                'keywords', ke.keywords,
                'version', ke.version,
                'created_at', ke.created_at,
                'similarity', r.similarity,
                'sources', COALESCE(sa.sources, '[]'::jsonb)
            ) AS entry
        FROM ranked r
        JOIN kb_entries ke ON ke.id = r.entry_id
        LEFT JOIN source_agg sa ON sa.kb_entry = ke.id
        ORDER BY r.similarity DESC
    )
    SELECT jsonb_agg(fe.entry)
    INTO result
    FROM final_entries fe;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$function$;

CREATE OR REPLACE FUNCTION public.search_related_snippets(p_snippet_id uuid, p_language text DEFAULT 'english'::text, match_threshold double precision DEFAULT 0.7, match_count integer DEFAULT 5, candidate_multiplier integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    source_embedding vector(3072);
    source_sub_embedding vector(512);
    result jsonb;
BEGIN
    -- Get the source snippet's embedding and sub-vector
    SELECT embedding, sub_vector(embedding, 512)::vector(512)
    INTO source_embedding, source_sub_embedding
    FROM snippet_embeddings
    WHERE snippet = p_snippet_id;

    -- If no embedding found, return empty array
    IF source_embedding IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    -- Two-stage search:
    -- Stage 1: Fast approximate search using sub-vector (uses HNSW index)
    -- Stage 2: Re-rank using full embedding and apply threshold
    WITH sub_similar AS (
        SELECT
            se.snippet as candidate_snippet_id,
            se.embedding
        FROM snippet_embeddings se
        WHERE se.snippet != p_snippet_id
        ORDER BY sub_vector(se.embedding, 512)::vector(512) <#> source_sub_embedding ASC
        LIMIT match_count * candidate_multiplier
    ),
    full_similar AS (
        SELECT
            candidate_snippet_id,
            1 - (embedding <=> source_embedding) as similarity
        FROM sub_similar
        WHERE 1 - (embedding <=> source_embedding) > match_threshold
        ORDER BY embedding <=> source_embedding ASC
        LIMIT match_count
    ),
    similar_snippets AS (
        SELECT
            s.id,
            s.title,
            s.file_path,
            s.recorded_at,
            s.comment_count,
            s.start_time,
            a.radio_station_name,
            a.radio_station_code,
            a.location_state,
            CASE
                WHEN p_language = 'spanish' THEN s.summary ->> 'spanish'
                ELSE s.summary ->> 'english'
            END AS summary,
            fs.similarity,
            jsonb_agg(l) as labels
        FROM full_similar fs
        JOIN snippets s ON s.id = fs.candidate_snippet_id
        JOIN audio_files a ON a.id = s.audio_file
        LEFT JOIN snippet_labels sl ON s.id = sl.snippet
        LEFT JOIN labels l ON sl.label = l.id
        WHERE s.status = 'Processed'
        GROUP BY
            s.id,
            s.title,
            s.file_path,
            s.recorded_at,
            s.comment_count,
            s.start_time,
            a.radio_station_name,
            a.radio_station_code,
            a.location_state,
            summary,
            fs.similarity
        ORDER BY fs.similarity DESC
    )
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', ss.id,
            'title', ss.title,
            'radio_station_name', ss.radio_station_name,
            'radio_station_code', ss.radio_station_code,
            'location_state', ss.location_state,
            'summary', ss.summary,
            'labels', ss.labels,
            'recorded_at', ss.recorded_at,
            'comment_count', ss.comment_count,
            'similarity', ss.similarity,
            'file_path', ss.file_path,
            'start_time', ss.start_time
        )
    ) INTO result
    FROM similar_snippets ss;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$function$;

CREATE OR REPLACE FUNCTION public.search_related_snippets_public(snippet_id uuid, p_language text DEFAULT 'english'::text, match_threshold double precision DEFAULT 0.7, match_count integer DEFAULT 5, candidate_multiplier integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    source_embedding vector(3072);
    source_sub_embedding vector(512);
    result jsonb;
BEGIN
    -- Get the source snippet's embedding
    SELECT embedding, sub_vector(embedding, 512)::vector(512)
    INTO source_embedding, source_sub_embedding
    FROM snippet_embeddings
    WHERE snippet = snippet_id;

    -- If no embedding found, return empty array
    IF source_embedding IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    WITH
    sub_similar_snippets AS (
        SELECT
            s.*,
            se.embedding
        FROM snippet_embeddings se
        JOIN snippets s ON s.id = se.snippet
        WHERE
            se.snippet != snippet_id
            AND s.status = 'Processed'
        ORDER BY
            sub_vector(embedding, 512)::vector(512) <#> source_sub_embedding ASC
        LIMIT match_count * candidate_multiplier
    ),
    similar_snippets AS (
        SELECT *
        FROM sub_similar_snippets
        WHERE -(embedding <#> source_embedding) > match_threshold -- Embedding is normalized so we can use inner product as similarity
        ORDER BY embedding <#> source_embedding ASC
        LIMIT match_count
    ),
    label_summary AS (
        SELECT
            sl.snippet,
            COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'text', l.text,
                        'text_spanish', l.text_spanish
                    )
                ),
                '[]'::jsonb
            ) AS labels
        FROM snippet_labels sl
        JOIN labels l ON l.id = sl.label
        WHERE sl.snippet IN (SELECT id FROM similar_snippets)
        GROUP BY sl.snippet
    ),
    final_snippets AS (
        SELECT
            s.id,
            s.title,
            s.file_path,
            s.recorded_at,
            s.comment_count,
            s.start_time,
            CASE
                WHEN p_language = 'spanish' THEN s.summary ->> 'spanish'
                ELSE s.summary ->> 'english'
            END AS summary,
            a.radio_station_name,
            a.radio_station_code,
            a.location_state,
            COALESCE(ls.labels, '[]'::jsonb) AS labels
        FROM similar_snippets s
        JOIN audio_files a ON a.id = s.audio_file
        LEFT JOIN label_summary ls ON ls.snippet = s.id
    )
    SELECT jsonb_agg(fs)
    INTO result
    FROM final_snippets fs;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$function$;

CREATE OR REPLACE FUNCTION public.setup_profile(first_name text, last_name text, avatar_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    metadata jsonb;
    result jsonb;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Create the metadata JSON object
    metadata := jsonb_build_object(
        'first_name', first_name,
        'last_name', last_name,
        'name', CONCAT(first_name, ' ', last_name),
        'full_name', CONCAT(first_name, ' ', last_name),
        'email', (SELECT email FROM auth.users WHERE id = current_user_id),
        'picture', avatar_url,
        'avatar_url', avatar_url
    );

    -- Update the user's profile in the auth.users table
    UPDATE auth.users
    SET
        raw_user_meta_data = metadata,
        updated_at = now() AT TIME ZONE 'utc'
    WHERE id = current_user_id;

    RETURN jsonb_build_object(
        'status', 'success',
        'message', 'Profile updated successfully'
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.sub_vector(v extensions.vector, dimensions integer)
 RETURNS extensions.vector
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
BEGIN
  IF dimensions > extensions.vector_dims(v) THEN
    RAISE EXCEPTION 'Dimensions must be less than or equal to the vector size';
  END IF;

  RETURN (
    WITH unnormed(elem) AS (
      SELECT x FROM unnest(v::float4[]) WITH ORDINALITY v(x, ix)
      WHERE ix <= dimensions
    ),
    norm(factor) AS (
      SELECT
        sqrt(sum(pow(elem, 2)))
      FROM
        unnormed
    )
    SELECT
      array_agg(u.elem / r.factor)::extensions.vector
    FROM
      norm r, unnormed u
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.toggle_recording_star(p_recording_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    recording_exists BOOLEAN;
    current_starred BOOLEAN;
    new_starred BOOLEAN;
BEGIN
    SELECT EXISTS(SELECT 1 FROM audio_files WHERE id = p_recording_id) INTO recording_exists;
    IF NOT recording_exists THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Recording not found');
    END IF;

    SELECT COALESCE(starred, FALSE) INTO current_starred FROM audio_files WHERE id = p_recording_id;
    new_starred := NOT current_starred;

    UPDATE audio_files SET starred = new_starred, updated_at = NOW() WHERE id = p_recording_id;

    RETURN jsonb_build_object('success', TRUE, 'starred', new_starred, 'recording_id', p_recording_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.toggle_star_snippet(snippet_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Check if the user has already starred the snippet
    IF EXISTS (
        SELECT 1
        FROM user_star_snippets
        WHERE "user" = current_user_id AND snippet = snippet_id
    ) THEN
        -- User has already starred the snippet, so remove the star
        DELETE FROM user_star_snippets
        WHERE "user" = current_user_id AND snippet = snippet_id;

        RETURN jsonb_build_object('data', jsonb_build_object('message', 'Snippet unstarred', 'snippet_starred', FALSE));
    ELSE
        -- User has not starred the snippet, so add a star
        INSERT INTO user_star_snippets ("user", snippet)
        VALUES (current_user_id, snippet_id);

        RETURN jsonb_build_object('data', jsonb_build_object('message', 'Snippet starred', 'snippet_starred', TRUE));
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.toggle_upvote_label(snippet_id uuid, label_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    label_id UUID;
    is_ai_suggested BOOLEAN;
    snippet_label_id UUID;
    label_upvote_id UUID;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Get the label ID and is_ai_suggested for the specified label text
    SELECT l.id, l.is_ai_suggested
    INTO label_id, is_ai_suggested
    FROM public.labels l
    WHERE l.text = label_text OR l.text_spanish = label_text
    LIMIT 1;

    IF label_id IS NULL THEN
        RETURN jsonb_build_object('data', jsonb_build_object('message', 'The label does not exist'));
    END IF;

    -- Get the snippet_label_id for the specified snippet and label
    snippet_label_id := (SELECT id FROM public.snippet_labels WHERE snippet = snippet_id AND label = label_id LIMIT 1);

    IF snippet_label_id IS NULL THEN
        RETURN jsonb_build_object('data', jsonb_build_object('message', 'The label has not been applied to the snippet'));
    END IF;

    -- Check if the label has been upvoted by the current user
    label_upvote_id := (SELECT id FROM public.label_upvotes WHERE upvoted_by = current_user_id AND snippet_label = snippet_label_id LIMIT 1);

    IF label_upvote_id IS NOT NULL THEN
        -- If upvoted, remove the upvote
        DELETE FROM public.label_upvotes WHERE id = label_upvote_id;

        -- Check if the label should be deleted: the label was not suggested by AI and has zero upvotes
        IF is_ai_suggested = false AND
            (SELECT COUNT(*) FROM public.label_upvotes WHERE snippet_label = snippet_label_id) = 0 THEN
            -- Delete the label
            DELETE FROM public.labels WHERE id = label_id;
        END IF;

        RETURN jsonb_build_object('data', jsonb_build_object('message', 'Label has been un-upvoted successfully'));
    ELSE
        -- If not upvoted, add the upvote
        INSERT INTO public.label_upvotes (upvoted_by, snippet_label) VALUES (current_user_id, snippet_label_id);
        RETURN jsonb_build_object('data', jsonb_build_object('message', 'Label has been upvoted successfully'));
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.toggle_welcome_card(p_status boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$DECLARE
    current_user_id UUID;
    metadata jsonb;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Get existing metadata and create new object
    SELECT COALESCE(raw_user_meta_data, '{}'::jsonb) || 
           jsonb_build_object('dismiss_welcome_card', p_status)
    INTO metadata
    FROM auth.users
    WHERE id = current_user_id;

    -- Update the user's profile in the auth.users table
    UPDATE auth.users
    SET
        raw_user_meta_data = metadata,
        updated_at = now() AT TIME ZONE 'utc'
    WHERE id = current_user_id;

    RETURN jsonb_build_object('status', 'success', 'message', 'Welcome card has been updated');
END;$function$;

CREATE OR REPLACE FUNCTION public.track_user_signups(origin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    sign_up_date TIMESTAMP WITH TIME ZONE;
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Retrieve the sign_up_date from the auth.users table
    SELECT created_at INTO sign_up_date
    FROM auth.users
    WHERE id = current_user_id;

    -- Check if the sign_up_date is more than 1 hour ago
    IF sign_up_date < (NOW() - INTERVAL '1 hour') THEN
        RETURN jsonb_build_object(
            'status', 'failed',
            'message', 'Sign-up date is more than 1 hour ago'
        );
    END IF;

    -- Check if the record already exists
    IF EXISTS (SELECT 1 FROM profiles.user_signups WHERE id = current_user_id) THEN
        RETURN jsonb_build_object(
            'status', 'failed',
            'message', 'User has already signed up'
        );
    END IF;

    -- Insert into table profiles.user_signups
    INSERT INTO profiles.user_signups (id, origin)
    VALUES (current_user_id, origin);

    RETURN jsonb_build_object(
        'status', 'success',
        'message', 'Success'
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.undo_upvote_label(snippet_id uuid, label_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE 
    current_user_id UUID; 
    label_id UUID; 
    is_ai_suggested BOOLEAN; 
    snippet_label_id UUID; 
BEGIN 
    -- Check if the user is authenticated 
    current_user_id := auth.uid(); 
    IF current_user_id IS NULL THEN 
        RAISE EXCEPTION 'Only logged-in users can call this function'; 
    END IF; 

    -- Get the label ID and is_ai_suggested for the specified label text 
    SELECT l.id, l.is_ai_suggested 
    INTO label_id, is_ai_suggested 
    FROM public.labels l 
    WHERE l.text = label_text 
    LIMIT 1; 

    -- Get the snippet_label_id for the specified snippet and label 
    snippet_label_id := (SELECT id FROM public.snippet_labels WHERE snippet = snippet_id AND label = label_id LIMIT 1); 

    -- Delete the upvote record if it exists 
    DELETE FROM public.label_upvotes 
    WHERE upvoted_by = current_user_id 
      AND snippet_label = snippet_label_id; 

    -- Check if the label should be deleted 
    IF label_id IS NOT NULL THEN 
        -- Check if the label was not suggested by AI and has zero upvotes 
        IF is_ai_suggested = false AND 
           (SELECT COUNT(*) FROM public.label_upvotes WHERE snippet_label = snippet_label_id) = 0 THEN 
            -- Delete the label 
            DELETE FROM public.labels WHERE id = label_id; 
        END IF; 
    END IF; 

    -- Return the result of the get_snippet_labels function 
    RETURN get_snippet_labels(snippet_id); 
END; 
$function$;

CREATE OR REPLACE FUNCTION public.unhide_snippet(snippet_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    user_roles text[];
BEGIN
    -- Check if the user is authenticated
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Only logged-in users can call this function';
    END IF;

    -- Get the roles of the current user
    user_roles := get_roles();

    -- Check if the user has the admin role
    IF 'admin' = ANY(user_roles) THEN
        -- Delete the record in the table `user_hide_snippets` (if any)
        DELETE FROM public.user_hide_snippets
        WHERE snippet = snippet_id;

        RETURN jsonb_build_object('status', 'success', 'message', 'Snippet has been unhidden successfully');
    END IF;

    RETURN jsonb_build_object('status', 'error', 'message', 'Only admin users can unhide the snippet');
END;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_prompt_version(p_stage text, p_version text, p_description text, p_created_by text, p_system_instruction text DEFAULT NULL::text, p_user_prompt text DEFAULT NULL::text, p_output_schema jsonb DEFAULT NULL::jsonb, p_set_active boolean DEFAULT true, p_sub_stage text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    new_version_id UUID;
    result jsonb;
BEGIN
    -- Insert new version (always as inactive first)
    INSERT INTO public.prompt_versions (
        stage, sub_stage, version, description, created_by,
        system_instruction, user_prompt, output_schema, is_active
    ) VALUES (
        p_stage, p_sub_stage, p_version, p_description, p_created_by,
        p_system_instruction, p_user_prompt, p_output_schema, FALSE
    )
    RETURNING id INTO new_version_id;

    -- If set_active, atomically deactivate others and activate this one
    IF p_set_active THEN
        UPDATE public.prompt_versions
        SET is_active = FALSE
        WHERE stage = p_stage
          AND sub_stage IS NOT DISTINCT FROM p_sub_stage
          AND id != new_version_id
          AND is_active = TRUE;

        UPDATE public.prompt_versions
        SET is_active = TRUE
        WHERE id = new_version_id;
    END IF;

    -- Return the new version info
    SELECT jsonb_build_object(
        'id', id,
        'stage', stage,
        'sub_stage', sub_stage,
        'version', version,
        'is_active', is_active
    ) INTO result
    FROM public.prompt_versions
    WHERE id = new_version_id;

    RETURN result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.upvote_label(snippet_id uuid, label_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE 
    current_user_id UUID; 
    snippet_label_id UUID; 
    label_id UUID; 
BEGIN 
    -- Check if the user is authenticated 
    current_user_id := auth.uid(); 
    IF current_user_id IS NULL THEN 
        RAISE EXCEPTION 'Only logged-in users can call this function'; 
    END IF;

    -- Check if the label exists 
    SELECT id INTO label_id 
    FROM public.labels 
    WHERE text = label_text 
    LIMIT 1; 
    IF label_id IS NULL THEN 
        RAISE EXCEPTION 'The label with text ''%'' does not exist.', label_text; 
    END IF; 

    -- Check if the found label has been applied to the given snippet or not 
    SELECT id INTO snippet_label_id 
    FROM public.snippet_labels 
    WHERE snippet = snippet_id AND label = label_id; 
    IF snippet_label_id IS NULL THEN 
        RAISE EXCEPTION 'The label ''%'' has not been applied to the given snippet yet.', label_text; 
    END IF; 

    -- Proceed to upvote the label
    INSERT INTO public.label_upvotes (upvoted_by, snippet_label)
    VALUES (current_user_id, snippet_label_id)
    ON CONFLICT (upvoted_by, snippet_label) DO NOTHING;

    -- Return the result of the get_snippet_labels function 
    RETURN get_snippet_labels(snippet_id); 
END; 
$function$;


