-- --------------------------------------------------------------------------
-- Policies
-- --------------------------------------------------------------------------

CREATE POLICY "Enable read access for authenticated users only" ON public.audio_files
    AS PERMISSIVE
    FOR SELECT
    TO authenticated
    USING (true);
CREATE POLICY "Enable access ony to server role" ON public.comment_reactions
    AS PERMISSIVE
    FOR ALL
    TO service_role
    USING (true);
CREATE POLICY "Enable full access for service role" ON public.downvote_review_queue
    AS PERMISSIVE
    FOR ALL
    TO service_role
    USING (true);
CREATE POLICY "Enable read access for authenticated users" ON public.downvote_review_queue
    AS PERMISSIVE
    FOR SELECT
    TO authenticated
    USING (true);
CREATE POLICY "Enable full access for service role" ON public.kb_entries
    AS PERMISSIVE
    FOR ALL
    TO service_role
    USING (true);
CREATE POLICY "Enable read access for authenticated users" ON public.kb_entries
    AS PERMISSIVE
    FOR SELECT
    TO authenticated
    USING (true);
CREATE POLICY "Enable full access for service role" ON public.kb_entry_embeddings
    AS PERMISSIVE
    FOR ALL
    TO service_role
    USING (true);
CREATE POLICY "Enable full access for service role" ON public.kb_entry_snippet_usage
    AS PERMISSIVE
    FOR ALL
    TO service_role
    USING (true);
CREATE POLICY "Enable read access for authenticated users" ON public.kb_entry_snippet_usage
    AS PERMISSIVE
    FOR SELECT
    TO authenticated
    USING (true);
CREATE POLICY "Enable full access for service role" ON public.kb_entry_sources
    AS PERMISSIVE
    FOR ALL
    TO service_role
    USING (true);
CREATE POLICY "Enable read access for authenticated users" ON public.kb_entry_sources
    AS PERMISSIVE
    FOR SELECT
    TO authenticated
    USING (true);
CREATE POLICY "Enable read access for authenticated users only" ON public.label_upvotes
    AS PERMISSIVE
    FOR SELECT
    TO authenticated
    USING (true);
CREATE POLICY "Enable read access for authenticated users only" ON public.labels
    AS PERMISSIVE
    FOR SELECT
    TO authenticated
    USING (true);
CREATE POLICY "Allow read access to prompt_versions" ON public.prompt_versions
    AS PERMISSIVE
    FOR SELECT
    TO public
    USING (true);
CREATE POLICY "Enable read access for authenticated users only" ON public.snippet_labels
    AS PERMISSIVE
    FOR SELECT
    TO authenticated
    USING (true);
CREATE POLICY "Enable read access for authenticated users only" ON public.snippets
    AS PERMISSIVE
    FOR SELECT
    TO authenticated
    USING (true);

