-- --------------------------------------------------------------------------
-- Comments
-- --------------------------------------------------------------------------

COMMENT ON TABLE public.comments IS 'Comment table';
COMMENT ON TABLE public.email_template IS 'Contain templates for email notification or other services';
COMMENT ON TABLE public.label_upvotes IS 'This table defines which user upvoted which label in a snippet.';
COMMENT ON TABLE public.snippet_labels IS 'When a label is applied to a snippet, it is called a "snippet label"';
COMMENT ON COLUMN public.audio_files.file_size IS '(in bytes)';
COMMENT ON COLUMN public.audio_files.status IS 'Possible values are: "New", "Processing", "Processed" and "Error"';
COMMENT ON COLUMN public.label_upvotes.upvoted_by IS 'The user who upvoted the snippet_label';
COMMENT ON COLUMN public.label_upvotes.snippet_label IS 'The snippet label that got upvoted';
COMMENT ON COLUMN public.snippet_embeddings.snippet_document IS 'The document text used for embedding generation';
COMMENT ON COLUMN public.snippet_embeddings.status IS 'Should be either "Processed" or "Error"';
COMMENT ON COLUMN public.snippets.start_time IS 'When the snippet begins, in HH:MM:SS format, relative to the start of the audio clip';
COMMENT ON COLUMN public.snippets.end_time IS 'When the snippet ends, in HH:MM:SS format, relative to the start of the audio clip';
COMMENT ON COLUMN public.snippets.file_path IS 'R2 location where the snippet clip is stored';
COMMENT ON COLUMN public.snippets.file_size IS '(in bytes)';
COMMENT ON COLUMN public.snippets.disinformation_categories IS 'Applicable categories based on heuristics';
COMMENT ON COLUMN public.snippets.keywords_detected IS 'Specific words or phrases that triggered the flag';
COMMENT ON COLUMN public.snippets.language IS 'Including primary_language, dialect and register';
COMMENT ON COLUMN public.snippets.confidence_scores IS 'Include "overall" score and "categories" scores (which is the score for each assigned category)';
COMMENT ON COLUMN public.snippets.status IS 'Possible values are: "New", "Processing", "Processed" and "Error"';
COMMENT ON COLUMN public.snippets.context IS 'Up to 100 words before/after the snippet';
COMMENT ON COLUMN public.snippets.stage_1_llm_response IS 'LLM response that led to the creation of this snippet';
COMMENT ON COLUMN public.snippets.duration IS 'Duration of the snippet clip';
COMMENT ON COLUMN public.snippets.user_last_activity IS 'Timestamp of last user activity';
COMMENT ON COLUMN public.snippets.previous_analysis IS 'This field stores the analysis result (stage 3) before reviewing (stage 4)';
COMMENT ON COLUMN public.snippets.reviewed_by IS 'The LLM name that was used for reviewing';
COMMENT ON COLUMN public.stage_1_llm_responses.audio_file IS 'Foreign key to an audio file';
COMMENT ON COLUMN public.stage_1_llm_responses.status IS 'Possible values are: "New", "Processing", "Processed" and "Error"';
COMMENT ON COLUMN public.stage_1_llm_responses.detection_result IS 'Detection result of Gemini 1.5 Pro 002';
COMMENT ON COLUMN public.stage_1_llm_responses.timestamped_transcription IS 'Timestamped transcription of the audio clip from OpenAI Whisper 1 (large-v2)';
COMMENT ON COLUMN public.stage_1_llm_responses.initial_transcription IS 'Initial transcription of the audio clip by Gemini 1.5 Flash 002';
COMMENT ON COLUMN public.stage_1_llm_responses.initial_detection_result IS 'Initial disinformation detection result from Gemini 1.5 Pro 002';
COMMENT ON COLUMN public.stage_1_llm_responses.transcriptor IS 'The LLM model that was used to create timestamped transcript of the audio';
COMMENT ON COLUMN public.user_like_snippets.value IS 'Value can either be: 1 (like), -1 (dislike) or 0 (neutral)';

